/* =========================================================
 * Scan grid : 2D azimuth only
 * ========================================================= */
#define AZ_STEP_DEG     (2)
#define AZ_MIN_DEG      (0)
#define AZ_MAX_DEG      (359)
/* 2D only */
#define EL_STEP_DEG     (1)
#define EL_MIN_DEG      (0)
#define EL_MAX_DEG      (0)
/* =========================================================
 * GCC band limit
 * ========================================================= */
#define SRP_FMIN_HZ     (800.0f)
#define SRP_FMAX_HZ     (3600.0f)
/* =========================================================
 * PHAT mode
 * ========================================================= */
#define PHAT_MODE_FULL      1
#define PHAT_MODE_SOFT05    2
#define PHAT_MODE           PHAT_MODE_FULL
/* =========================================================
 * SRP-PHAT root-cause test profiles
 *
 * Change ONLY SRP_TEST_PROFILE and rebuild.
 *   0: original FULL PHAT baseline
 *   1: FULL + per-frequency-bin noise/SNR gate
 *   2: FULL + temporal magnitude-squared coherence weighting
 *   3: FULL + microphone-pair consistency gate
 *   4: FULL + Top1/Top2 peak-confidence gate
 *   5: FULL + 3-sub-band direction voting
 *   6: ALL features enabled (heaviest CPU load)
 *   7: SNR + coherence (front-end test)
 *   8: SNR + coherence + pair + peak confidence (recommended first test)
 * ========================================================= */
#define SRP_TEST_PROFILE_BASELINE_FULL       0
#define SRP_TEST_PROFILE_BIN_SNR             1
#define SRP_TEST_PROFILE_COHERENCE           2
#define SRP_TEST_PROFILE_PAIR_CONSISTENCY    3
#define SRP_TEST_PROFILE_PEAK_CONFIDENCE     4
#define SRP_TEST_PROFILE_SUBBAND_VOTING      5
#define SRP_TEST_PROFILE_ALL                 6
#define SRP_TEST_PROFILE_FRONTEND            7
#define SRP_TEST_PROFILE_RECOMMENDED         8
#ifndef SRP_TEST_PROFILE
#define SRP_TEST_PROFILE SRP_TEST_PROFILE_ALL
#endif
#if (SRP_TEST_PROFILE == SRP_TEST_PROFILE_BIN_SNR) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_ALL) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_FRONTEND) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_RECOMMENDED)
#define SRP_USE_BIN_SNR_GATE              1
#else
#define SRP_USE_BIN_SNR_GATE              0
#endif
#if (SRP_TEST_PROFILE == SRP_TEST_PROFILE_COHERENCE) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_ALL) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_FRONTEND) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_RECOMMENDED)
#define SRP_USE_COHERENCE_WEIGHT          1
#else
#define SRP_USE_COHERENCE_WEIGHT          0
#endif
#if (SRP_TEST_PROFILE == SRP_TEST_PROFILE_PAIR_CONSISTENCY) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_ALL) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_RECOMMENDED)
#define SRP_USE_PAIR_CONSISTENCY          1
#else
#define SRP_USE_PAIR_CONSISTENCY          0
#endif
#if (SRP_TEST_PROFILE == SRP_TEST_PROFILE_PEAK_CONFIDENCE) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_ALL) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_RECOMMENDED)
#define SRP_USE_PEAK_CONFIDENCE           1
#else
#define SRP_USE_PEAK_CONFIDENCE           0
#endif
#if (SRP_TEST_PROFILE == SRP_TEST_PROFILE_SUBBAND_VOTING) || \
    (SRP_TEST_PROFILE == SRP_TEST_PROFILE_ALL)
#define SRP_USE_SUBBAND_VOTING            1
#else
#define SRP_USE_SUBBAND_VOTING            0
#endif
/* Spectral-noise learning: update only while RMS gate says silence. */
#define SRP_NOISE_EMA_NEW                  (0.04f)
#define SRP_NOISE_MIN_LEARN_FRAMES         12U
#define SRP_BIN_SNR_RATIO_ZERO             (1.20f)
#define SRP_BIN_SNR_RATIO_FULL             (2.50f)
/* Temporal coherence weighting. Single-frame coherence is always ~1,
 * therefore exponentially smoothed auto/cross spectra are used. */
#define SRP_COH_EMA_NEW                    (0.18f)
#define SRP_COH_MIN_FRAMES                 6U
#define SRP_COH_ZERO                       (0.35f)
#define SRP_COH_FULL                       (0.75f)
/* Pair-consistency: candidate lag must be at least this fraction of
 * each pair's current positive GCC peak. */
#define SRP_PAIR_SUPPORT_PEAK_RATIO        (0.30f)
#define SRP_PAIR_MIN_SUPPORT               5U
/* Broadband SRP peak confidence. */
#define SRP_PEAK_CONF_SEP_DEG              (45.0f)
#define SRP_PEAK_CONF_RATIO_MIN            (1.10f)
#define SRP_PEAK_CONF_ABS_MIN              PRIMARY_DOA_FALLBACK_SCORE
/* 3-band speech voting. CPU cost is intentionally higher; use profile 5
 * first before enabling profile 6. */
#define SRP_SUBBAND_COUNT                  3
#define SRP_SUBBAND0_FMIN_HZ               (800.0f)
#define SRP_SUBBAND0_FMAX_HZ               (1400.0f)
#define SRP_SUBBAND1_FMIN_HZ               (1400.0f)
#define SRP_SUBBAND1_FMAX_HZ               (2200.0f)
#define SRP_SUBBAND2_FMIN_HZ               (2200.0f)
#define SRP_SUBBAND2_FMAX_HZ               (3600.0f)
#define SRP_SUBBAND_AGREE_DEG              (30.0f)
#define SRP_SUBBAND_SEARCH_GATE_DEG        (35.0f)
#define SRP_SUBBAND_MIN_AGREE              2U
#define SRP_AZ_COUNT (((AZ_MAX_DEG - AZ_MIN_DEG) / AZ_STEP_DEG) + 1)
#define SRP_DEBUG_PAIR_INDEX               0U
/* =========================================================
 * Pair weighting
 * ========================================================= */
#define USE_BASELINE2_WEIGHT  1
/* =========================================================
 * Smoothing
 * ========================================================= */
#define DOA_SMOOTH_ENABLE   1
#define DOA_SMOOTH_ALPHA    (0.2f)
/* =========================================================
 * Top-K / track : 2 outputs only
 * ========================================================= */
#define TOPK_DOA                	2
#define MAX_TRACKS              	2
#define TOPK_AZ_SEP_DEG         	45.0f
#define TOPK_EL_SEP_DEG         	180.0f
#define TRACK_MATCH_AZ_DEG      	35.0f
#define TRACK_MATCH_EL_DEG      	180.0f
#define ACTIVE_TRACK_MIN_SEP_DEG 	25.0f
#define TRACK_BIRTH_SCORE       	(0.00020f)
#define PRIMARY_DOA_FALLBACK_SCORE  (0.00005f)
#define TRACK_DEATH_MISS        	10
#define TRACK_SMOOTH_ALPHA      	(0.35f)
/* =========================================================
 * Prediction / association
 * ========================================================= */
#define TRACK_VEL_SMOOTH_ALPHA      (0.12f)
#define TRACK_VEL_DAMP_WHEN_MISS    (0.92f)
#define ASSOC_COST_INVALID          (1e9f)
#define ASSOC_COST_SCORE_WEIGHT     (1500.0f)
#define ASSOC_COST_AGE_BONUS        (1.0f)
#define SLOT_COAST_MISS             (10)
/* =========================================================
 * Kalman filter for azimuth track
 * state x = [az_unwrapped_deg, az_vel_deg_per_frame]^T
 * ========================================================= */
#define KF_DT_SEC                   ((float)HOP_SIZE / FS)
/* process noise */
#define KF_Q_AZ                     (6.0f)     /* deg^2 */
#define KF_Q_VEL                    (1.0f)     /* (deg/frame)^2 */
/* measurement noise */
#define KF_R_BASE                   (8.0f)     /* deg^2 */
#define KF_R_SCORE_SCALE            (0.020f)   /* larger => score affects R more */
#define KF_R_MIN                    (1.5f)
#define KF_R_MAX                    (40.0f)
/* initial covariance on birth */
#define KF_P00_INIT                 (25.0f)
#define KF_P01_INIT                 (0.0f)
#define KF_P10_INIT                 (0.0f)
#define KF_P11_INIT                 (4.0f)
/* association gate */
#define TRACK_MATCH_SIGMA_GATE      (3.0f)     /* ~3 sigma gate */
#define ASSOC_COST_MAHAL_WEIGHT     (1.0f)
#define ASSOC_COST_SCORE_WEIGHT_KF  (600.0f)
#define ASSOC_COST_AGE_BONUS_KF     (0.5f)
/* =========================================================
 * Silence hold
 * ========================================================= */
#define SILENCE_HOLD_HOPS           80u
#define SILENCE_DECAY_STRIDE        8u
/*
 * LED hold is independent from PHAT mode and persistent track ID.
 * SOFT05 can temporarily output a valid fallback DOA with track id=0;
 * without this extra hold the LED is cleared as soon as silence starts.
 *
 * Match the effective FULL-mode coast time:
 *   80 hold hops + 11 decay steps * 8 hops = 168 hops
 *   168 * 256 / 16000 = about 2.69 seconds.
 */
#define LED_HOLD_HOPS               (SILENCE_HOLD_HOPS + \
                                     ((TRACK_DEATH_MISS + 1u) * SILENCE_DECAY_STRIDE))
/* =========================================================
 * Beamforming / synthesis
 * ========================================================= */
#define OUTPUT_GAIN         (1.0f / NMIC)
/* =========================================================
 * Soft mask
 * ========================================================= */
#define SOFTMASK_ENABLE         1
#define SOFTMASK_BETA           (10.0f)
#define SOFTMASK_MIN_SCORE      (1e-6f)
#define SOFTMASK_USE_BANDLIMIT  1
/* =========================================================
 * TDOA-LS elevation refinement for planar 4-mic array
 *
 * Method A:
 *   SRP-PHAT top2 azimuth candidates are kept.
 *   For each candidate, GCC peak candidates are assigned exclusively
 *   per pair, then planar TDOA LS estimates |elevation|.
 *
 * Limitation:
 *   Because all microphones are coplanar, this estimates absolute
 *   elevation only. +el and -el are indistinguishable.
 * ========================================================= */
#define TDOA_ELEVATION_ENABLE        1
#define TDOA_ASSUME_SOURCE_ABOVE_ARRAY 1
#define TDOA_MAX_PEAKS_PER_PAIR      6
#define TDOA_PEAK_MIN_SEP_SAMP       (0.60f)
/* 16 kHz / 30 mm array has only ~1.4 sample adjacent delay.
 * Start around 0.55~0.75. Increase if high elevation is missed;
 * decrease if tracks steal each other's peaks. */
#define TDOA_ASSIGN_GATE_SAMP        (0.65f)
#define TDOA_MIN_VALID_PAIRS         4
#define TDOA_LS_RESID_MAX_M          (0.012f)
#define TDOA_LS_EL_SMOOTH_ALPHA      (0.20f)
#define TDOA_MAX_EL_DEG              (90.0f)
#define TDOA_MIN_RHO                 (0.0f)
#define TDOA_MISSING_PAIR_COST       (0.90f)
#define TDOA_PEAK_SCORE_COST_WEIGHT  (0.20f)
/* =========================================================
 * Second-code elevation method graft
 *
 * Keep this file's existing azimuth/tracking/public API flow.
 * Only the elevation calculation is taken from the second attached code:
 *   selected azimuth -> constrained elevation SRP scan -> smoothed 0..90 deg el.
 *
 * Planar-array limitation:
 *   Because all microphones are coplanar(z=0), +el and -el cannot be
 *   distinguished. The result is an absolute elevation in the upper hemisphere.
 * ========================================================= */
#define SECOND_CODE_ELEVATION_ENABLE     1
#define SECOND_TDOA_LS_EL_MIN_DEG        (0.0f)
#define SECOND_TDOA_LS_EL_MAX_DEG        (90.0f)
#define SECOND_EL_SRP_SCAN_ENABLE        1
#define SECOND_EL_SRP_MIN_DEG            (0)
#define SECOND_EL_SRP_MAX_DEG            (90)
#define SECOND_EL_SRP_STEP_DEG           (1)
#define SECOND_EL_SRP_SMOOTH_ALPHA       (0.65f)
#define SECOND_EL_SRP_PARABOLIC_REFINE   1
#define SECOND_EL_SRP_DEADBAND_DEG       (0.8f)
#define SECOND_EL_TURN_LOCK_MAX_STEP_DEG (4.0f)
#define SECOND_EL_CONF_GATE_ENABLE       1
#define SECOND_EL_CONF_RATIO_MIN         (1.08f)
#define SECOND_EL_CONF_ABS_MIN           (1e-12f)
#define SECOND_EL_CONF_SEP_DEG           (6)
#define SECOND_EL_CONF_HOLD_ON_LOW       1
/* =========================================================
 * Adaptive RMS gate *
 * 기존 고정 gate (ON=200 / OFF=150) 대신 주변 무음 RMS를
 * noise floor로 천천히 추정하고 threshold를 자동 조정합니다.
 *
 * 16 kHz / HOP_SIZE=256 기준:
 *   ON_CONFIRM_HOPS  = 2  -> 약 32 ms 연속 초과 시 speech ON
 *   OFF_CONFIRM_HOPS = 10 -> 약 160 ms 연속 이하 시 speech OFF
 *
 * noise floor는 speech가 없는 동안에만 갱신합니다.
 * speech 중에는 freeze하여 음성 자체를 noise로 학습하지 않습니다.
 * ========================================================= */
#define RMS_ADAPTIVE_GATE_ENABLE       1U
#define RMS_NOISE_FLOOR_INIT           (45.0f)
#define RMS_NOISE_FLOOR_MIN            (10.0f)
#define RMS_NOISE_FLOOR_MAX            (2000.0f)
/* noise가 커질 때는 천천히, 작아질 때는 조금 더 빠르게 추종 */
#define RMS_NOISE_ALPHA_RISE           (0.02f)
#define RMS_NOISE_ALPHA_FALL           (0.05f)
#define RMS_ON_RATIO                   (2.70f)
#define RMS_OFF_RATIO                  (1.50f)
/* 너무 조용한 환경에서 threshold가 과도하게 내려가는 것 방지 */
#define RMS_ON_MIN                     (60.0f)
#define RMS_OFF_MIN                    (45.0f)
#define RMS_ON_CONFIRM_HOPS            3U
#define RMS_OFF_CONFIRM_HOPS           10U
/* Adaptive gate를 끌 때 사용할 기존 fallback 값 */
#define RMS_PRESENT_ON_FIXED           200U
#define RMS_PRESENT_OFF_FIXED          150U
/* =========================================================
 * Debug
 * ========================================================= */
#define ENABLE_DEBUG_PRINT  0
/* UART1 DOA debug output.
 * Prints primary azimuth/elevation periodically without using USB CDC.
 * HOP_SIZE=256 at 16 kHz -> one DOA run is about 16 ms.
 * DECIM 20 -> about 320 ms between UART lines.
 */
#define DOA_UART_DEBUG_ENABLE       1U
#define DOA_UART_DEBUG_DECIM        1U
#define DOA_UART_DEBUG_TIMEOUT_MS   5U
/* =========================================================
 * Types
 * ========================================================= */
typedef struct { uint8_t i, j; } pair_t;
typedef struct {
    float lag;   /* samples, can be fractional */
    float val;   /* GCC-PHAT value at lag */
    uint8_t valid;
} lag_peak_t;
typedef struct {
    float az;
    float el;
    float score;
    /* elevation refinement status */
    uint8_t el_valid;
    float el_resid;
} doa_cand_t;
typedef struct {
    uint8_t active;
    uint32_t id;
    uint32_t born_seq;
    /* wrapped output state for public use */
    float az_deg;
    float el_deg;
    float score;
    uint8_t el_valid;
    float el_resid;
    /* kept for compatibility / debug */
    float az_vel_deg;
    /* Kalman internal state (unwrapped azimuth) */
    float kf_x0;   /* az_unwrapped_deg */
    float kf_x1;   /* az_vel_deg_per_frame */
    /* covariance P */
    float kf_P00, kf_P01;
    float kf_P10, kf_P11;
    uint32_t age;
    uint32_t miss;
    float tau_mic[NMIC];
    float tau_pair[NPAIR];
    float ola_tail[HOP_SIZE];
    int16_t out_hop_i16[HOP_SIZE];
} doa_track_t;
