volatile uint32_t g_sai1b_rms_ch0 = 0U;
volatile uint32_t g_sai1b_rms_ch1 = 0U;
volatile uint32_t g_sai1b_rms_ch2 = 0U;
volatile uint32_t g_sai1b_rms_ch3 = 0U;
/* =========================================================
 * Helpers
 * ========================================================= */
static void rfft_unpack_bins(const float *packed, float bins[NBINS][2])
{
    bins[0][0] = packed[0];
    bins[0][1] = 0.0f;
    bins[NBINS - 1][0] = packed[1];
    bins[NBINS - 1][1] = 0.0f;
    for (int k = 1; k < NBINS - 1; k++) {
        bins[k][0] = packed[2 * k];
        bins[k][1] = packed[2 * k + 1];
    }
}
static void bins_pack_rfft(const float bins[NBINS][2], float *packed_out)
{
    packed_out[0] = bins[0][0];
    packed_out[1] = bins[NBINS - 1][0];
    for (int k = 1; k < NBINS - 1; k++) {
        packed_out[2 * k]     = bins[k][0];
        packed_out[2 * k + 1] = bins[k][1];
    }
}
static inline float dot3(const float a[3], const float b[3])
{
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
}
static inline float clampf(float x, float lo, float hi)
{
    if (x < lo) return lo;
    if (x > hi) return hi;
    return x;
}
static inline float wrap_deg_360(float x)
{
    while (x < 0.0f) x += 360.0f;
    while (x >= 360.0f) x -= 360.0f;
    return x;
}
static inline float signed_angdiff_deg(float a, float b)
{
    float d = a - b;
    while (d > 180.0f) d -= 360.0f;
    while (d < -180.0f) d += 360.0f;
    return d;
}
static inline void unitvec_from_az_el(float az_deg, float el_deg, float u[3])
{
    float az = az_deg * (PI / 180.0f);
    float el = el_deg * (PI / 180.0f);
    float caz = arm_cos_f32(az);
    float saz = arm_sin_f32(az);
    float cel = arm_cos_f32(el);
    float sel = arm_sin_f32(el);
    u[0] = cel * caz;
    u[1] = cel * saz;
    u[2] = sel;
}
static inline float angdiff_deg(float a, float b)
{
    float d = fabsf(a - b);
    return (d > 180.0f) ? (360.0f - d) : d;
}
static inline int iabs_int(int x)
{
    return (x < 0) ? -x : x;
}
static inline int too_close(const doa_cand_t *c, const doa_cand_t *b)
{
    return (angdiff_deg(c->az, b->az) < TOPK_AZ_SEP_DEG);
}
static inline float fast_exp_approx(float x)
{
    return expf(x);
}
static inline float angle_lerp_deg(float cur, float meas, float a)
{
    float d = meas - cur;
    while (d > 180.0f) d -= 360.0f;
    while (d < -180.0f) d += 360.0f;
    cur += a * d;
    while (cur < 0.0f) cur += 360.0f;
    while (cur >= 360.0f) cur -= 360.0f;
    return cur;
}
static inline float unwrap_angle_near_ref_deg(float meas_wrapped, float ref_unwrapped)
{
    float base = wrap_deg_360(meas_wrapped);
    float ref_wrapped = wrap_deg_360(ref_unwrapped);
    float d = signed_angdiff_deg(base, ref_wrapped);
    return ref_unwrapped + d;
}
static inline float track_pred_az_unwrapped_deg(const doa_track_t *tr)
{
    return tr->kf_x0 + tr->kf_x1;
}
static inline float track_pred_az_wrapped_deg(const doa_track_t *tr)
{
    return wrap_deg_360(track_pred_az_unwrapped_deg(tr));
}
static inline float track_pred_az_deg(const doa_track_t *tr)
{
    return track_pred_az_wrapped_deg(tr);
}
static inline float kf_measurement_noise_from_score(float score)
{
    float R = KF_R_BASE;
    if (score > 1e-9f) {
        R = KF_R_BASE / (1.0f + score / KF_R_SCORE_SCALE);
    }
    return clampf(R, KF_R_MIN, KF_R_MAX);
}
/* =========================================================
 * First-sound-board selector for single MX-28AR motor
 * ========================================================= */
static uint32_t DOA_GetActiveStreamMask(void);
static uint8_t DOA_IsStreamActive(uint32_t stream_id);
#define FIRST_SOUND_ABS_THRESHOLD       700U
#define FIRST_SOUND_PAIR_WAIT_MS        50U
#define FIRST_SOUND_LOST_TIMEOUT_MS     1500U
#define FIRST_SOUND_BOARD_L_OFFSET_DEG  0.0f
#define FIRST_SOUND_BOARD_R_OFFSET_DEG  0.0f
#define FIRST_SOUND_BOARD_L_INVERT      0U
#define FIRST_SOUND_BOARD_R_INVERT      0U
typedef struct {
    uint8_t valid;
    uint8_t stream_id;
    uint32_t seq;
    uint32_t sample_index;
    uint32_t tick_ms;
    uint32_t rms;
} doa_first_candidate_t;
static doa_first_candidate_t s_first_candidate[AUDIO_STREAM_COUNT];
static uint8_t s_first_prev_present[AUDIO_STREAM_COUNT] = {0U, 0U};
static uint8_t s_first_selected_valid = 0U;
static uint8_t s_first_selected_stream = AUDIO_STREAM_L;
static uint32_t s_first_selected_seq = 0U;
static uint32_t s_first_selected_sample_index = 0U;
static uint32_t s_first_selected_rms = 0U;
static volatile doa_first_sound_target_t g_first_sound_motor_target = {0};
/* Sequence used by the motor layer to count only genuinely new DOA measurements. */
static uint32_t s_first_target_update_seq = 0U;
static uint32_t s_first_no_active_since_ms = 0U;

/*
 * CubeIDE Watch:
 * Number of times a 1.5 s real-silence boundary hard-reset the old DOA
 * tracking state. This makes it easy to verify that a new utterance cannot
 * inherit the previous azimuth track.
 */
volatile uint32_t g_doa_silence_track_reset_count = 0U;
static uint32_t DOA_abs_i16_u32(int16_t x)
{
    if (x < 0) {
        return (uint32_t)(-((int32_t)x));
    }
    return (uint32_t)x;
}

static float DOA_FirstSoundWrap360(float deg)
{
    while (deg < 0.0f) {
        deg += 360.0f;
    }
    while (deg >= 360.0f) {
        deg -= 360.0f;
    }
    return deg;
}
static uint8_t DOA_FirstSoundFindOnsetSample(const int16_t *hop_interleaved,
                                             uint32_t frames_per_ch,
                                             uint32_t nmic,
                                             uint32_t abs_threshold,
                                             uint32_t *out_sample_index)
{
    if ((hop_interleaved == NULL) || (out_sample_index == NULL)) {
        return 0U;
    }
    for (uint32_t n = 0U; n < frames_per_ch; n++) {
        uint32_t peak = 0U;
        for (uint32_t ch = 0U; ch < nmic; ch++) {
            uint32_t a = DOA_abs_i16_u32(hop_interleaved[(n * nmic) + ch]);
            if (a > peak) {
                peak = a;
            }
        }
        if (peak >= abs_threshold) {
            *out_sample_index = n;
            return 1U;
        }
    }
    return 0U;
}
static uint8_t DOA_FirstSoundIsEarlier(const doa_first_candidate_t *a, const doa_first_candidate_t *b)
{
    if (a->seq < b->seq) {
        return 1U;
    }
    if (a->seq > b->seq) {
        return 0U;
    }
    return (a->sample_index <= b->sample_index) ? 1U : 0U;
}
static float DOA_FirstSoundBoardAzToMotorAz(uint32_t stream_id, float board_az_deg)
{
    float az = board_az_deg;
    if (stream_id == AUDIO_STREAM_L) {
#if (FIRST_SOUND_BOARD_L_INVERT != 0U)
        az = 360.0f - az;
#endif
        az += FIRST_SOUND_BOARD_L_OFFSET_DEG;
    }
    else {
#if (FIRST_SOUND_BOARD_R_INVERT != 0U)
        az = 360.0f - az;
#endif
        az += FIRST_SOUND_BOARD_R_OFFSET_DEG;
    }
    return DOA_FirstSoundWrap360(az);
}
float DOA_ConvertBoardAzToMotorAz(uint32_t stream_id, float board_az_deg)
{
    return DOA_FirstSoundBoardAzToMotorAz(stream_id, board_az_deg);
}
static void DOA_FirstSoundSelect(const doa_first_candidate_t *cand)
{
    if ((cand == NULL) || (cand->valid == 0U)) {
        return;
    }
    if (s_first_selected_valid != 0U) {
        return;
    }
    s_first_selected_valid = 1U;
    s_first_selected_stream = cand->stream_id;
    s_first_selected_seq = cand->seq;
    s_first_selected_sample_index = cand->sample_index;
    s_first_selected_rms = cand->rms;
}
static void DOA_FirstSoundResolve(void)
{
    uint32_t now = HAL_GetTick();
    uint32_t active_mask = DOA_GetActiveStreamMask();
    uint8_t l_active = AUDIO_STREAM_MASK_HAS(active_mask, AUDIO_STREAM_L) ? 1U : 0U;
    uint8_t r_active = AUDIO_STREAM_MASK_HAS(active_mask, AUDIO_STREAM_R) ? 1U : 0U;
    if (s_first_selected_valid != 0U) {
        return;
    }
    /* L-only: select L immediately; do not wait 50 ms for R. */
    if ((l_active != 0U) && (r_active == 0U)) {
        if (s_first_candidate[AUDIO_STREAM_L].valid != 0U) {
            DOA_FirstSoundSelect(&s_first_candidate[AUDIO_STREAM_L]);
        }
        return;
    }
    if ((l_active == 0U) && (r_active != 0U)) {
        if (s_first_candidate[AUDIO_STREAM_R].valid != 0U) {
            DOA_FirstSoundSelect(&s_first_candidate[AUDIO_STREAM_R]);
        }
        return;
    }
    if ((l_active == 0U) && (r_active == 0U)) {
        return;
    }
    /* L+R: compare onset order when both candidates are available. */
    if ((s_first_candidate[AUDIO_STREAM_L].valid != 0U) &&
        (s_first_candidate[AUDIO_STREAM_R].valid != 0U)) {
        if (DOA_FirstSoundIsEarlier(&s_first_candidate[AUDIO_STREAM_L],
                                    &s_first_candidate[AUDIO_STREAM_R]) != 0U) {
            DOA_FirstSoundSelect(&s_first_candidate[AUDIO_STREAM_L]);
        }
        else {
            DOA_FirstSoundSelect(&s_first_candidate[AUDIO_STREAM_R]);
        }
        return;
    }
    if (s_first_candidate[AUDIO_STREAM_L].valid != 0U) {
        if ((now - s_first_candidate[AUDIO_STREAM_L].tick_ms) >= FIRST_SOUND_PAIR_WAIT_MS) {
            DOA_FirstSoundSelect(&s_first_candidate[AUDIO_STREAM_L]);
        }
    }
    if (s_first_candidate[AUDIO_STREAM_R].valid != 0U) {
        if ((now - s_first_candidate[AUDIO_STREAM_R].tick_ms) >= FIRST_SOUND_PAIR_WAIT_MS) {
            DOA_FirstSoundSelect(&s_first_candidate[AUDIO_STREAM_R]);
        }
    }
}
/*
 * 각 stream에서 무음 -> 소리 있음으로 바뀌는 순간을 잡는다.
 * Degree_ProcessOneStream()에서 present 계산 직후 호출.
 */
static void DOA_FirstSoundUpdateOnset(uint32_t stream_id,
                                      const int16_t *new_hop_interleaved,
                                      uint32_t snap_seq,
                                      uint32_t rms,
                                      uint8_t present)
{
    uint32_t sample_index = 0U;
    if ((stream_id >= AUDIO_STREAM_COUNT) ||
        (DOA_IsStreamActive(stream_id) == 0U)) {
        return;
    }
    if (s_first_selected_valid != 0U) {
        s_first_prev_present[stream_id] = present;
        return;
    }
    /*
     * rising edge: 이전 hop에서는 무음, 현재 hop에서는 소리 있음.
     */
    if ((present != 0U) && (s_first_prev_present[stream_id] == 0U)) {
        if (DOA_FirstSoundFindOnsetSample(new_hop_interleaved,
                                          AUDIO_HOP_SAMPLES_PER_CH,
                                          AUDIO_NMIC,
                                          FIRST_SOUND_ABS_THRESHOLD,
                                          &sample_index) == 0U) {
            sample_index = 0U;
        }
        s_first_candidate[stream_id].valid = 1U;
        s_first_candidate[stream_id].stream_id = (uint8_t)stream_id;
        s_first_candidate[stream_id].seq = snap_seq;
        s_first_candidate[stream_id].sample_index = sample_index;
        s_first_candidate[stream_id].tick_ms = HAL_GetTick();
        s_first_candidate[stream_id].rms = rms;
    }
    s_first_prev_present[stream_id] = present;
    DOA_FirstSoundResolve();
}
/*
 * 선택된 stream의 SRP-PHAT 결과가 active일 때만 모터 target 갱신.
 */
static void DOA_FirstSoundUpdateTarget(uint32_t stream_id,
                                       const doa_result_t *track,
                                       uint32_t rms)
{
    doa_first_sound_target_t t;
    if ((track == NULL) ||
        (stream_id >= AUDIO_STREAM_COUNT) ||
        (DOA_IsStreamActive(stream_id) == 0U)) {
        return;
    }
    /*
     * Speech release tail: keep the previously accepted motor target.
     * Do not let a late reverberation/noise DOA overwrite it.
     */
    if (DOA_IsRmsReleaseTailActive(stream_id) != 0U) {
        return;
    }
    DOA_FirstSoundResolve();
    if (s_first_selected_valid == 0U) {
        return;
    }
    if (stream_id != s_first_selected_stream) {
        return;
    }
    if (track->active == 0U) {
        return;
    }
    memset(&t, 0, sizeof(t));
    t.valid = 1U;
    t.stream_id = (uint8_t)stream_id;
    t.srp_az_deg = DOA_FirstSoundWrap360(track->az_deg);
    t.az_deg = DOA_FirstSoundBoardAzToMotorAz(stream_id, track->az_deg);
    t.el_deg = track->el_deg;
    t.el_valid = track->el_valid;
    t.el_raw_deg = track->el_raw_deg;
    t.el_resid = track->el_resid;
    t.track_id = track->id;
    t.first_seq = s_first_selected_seq;
    t.first_sample_index = s_first_selected_sample_index;
    t.rms = rms;
    s_first_target_update_seq++;
    if (s_first_target_update_seq == 0U) {
        s_first_target_update_seq = 1U;
    }
    t.update_seq = s_first_target_update_seq;
    g_first_sound_motor_target = t;
}

/*
 * Long-silence hard reset for DOA tracking.
 *
 * FIRST_SOUND_LOST_TIMEOUT_MS is the boundary at which the motor layer is
 * allowed to treat the next speech as a new event. The old implementation
 * reset only the first-sound target at that boundary, while the SRP/Kalman
 * track could remain alive longer. A new utterance could therefore latch the
 * previous azimuth before a fresh track was born.
 *
 * Reset here:
 *   - SRP/Kalman tracks and output-slot bindings
 *   - held azimuth/elevation used during coast
 *   - last DOA snapshot
 *   - DOA smoothing / secondary elevation tracking state
 *   - public latest-track snapshot and release-tail flags
 *
 * Intentionally keep:
 *   - CM4<->CM7 shared-memory HALF/FULL sequence state
 *   - input frame/warm-up state
 *   - learned adaptive RMS noise floor and thresholds
 *   - spectral noise model
 *
 * Keeping these avoids shortening far-field detection range or disturbing
 * the CM4<->CM7 audio transport when an utterance ends.
 */
static void DOA_ResetTrackingAfterLongSilence(void)
{
    uint32_t active_mask = DOA_GetActiveStreamMask();

    for (uint32_t stream = 0U; stream < AUDIO_STREAM_COUNT; stream++)
    {
        doa_stream_context_t *ctx = &g_doa_ctx[stream];

        if (!AUDIO_STREAM_MASK_HAS(active_mask, stream))
        {
            continue;
        }

        memset(ctx->tracks, 0, sizeof(ctx->tracks));
        ctx->slot_track_id[0] = 0U;
        ctx->slot_track_id[1] = 0U;

        /* Preserve monotonically increasing IDs across utterances. */
        if (ctx->next_track_id == 0U)
        {
            ctx->next_track_id = 1U;
        }
        if (ctx->next_born_seq == 0U)
        {
            ctx->next_born_seq = 1U;
        }

        memset(&ctx->last_doa, 0, sizeof(ctx->last_doa));

        ctx->hold_az_l = 0.0f;
        ctx->hold_el_l = 0.0f;
        ctx->hold_az_r = 0.0f;
        ctx->hold_el_r = 0.0f;
        ctx->hold_valid_l = 0U;
        ctx->hold_valid_r = 0U;

        ctx->smooth_init = 0U;
        ctx->az_sin = 0.0f;
        ctx->az_cos = 1.0f;
        ctx->el_smooth = 0.0f;

        ctx->second_el_track_valid = 0U;
        ctx->second_el_track_deg = 0.0f;
        ctx->second_el_track_score = 0.0f;
        ctx->second_el_conf_ratio = 999.0f;
        ctx->second_el_conf_ok = 1U;
        ctx->second_force_el_snap = 1U;

        /* Gate is already in silence. Clear transient confirmation counters
         * only; keep learned noise floor and thresholds. */
        ctx->rms_on_count = 0U;
        ctx->rms_off_count = 0U;

        if (stream < DOA_MAX_SOURCES)
        {
            memset((void *)&g_latest_tracks[stream], 0,
                   sizeof(g_latest_tracks[stream]));
            g_doa_rms_release_tail_stream[stream] = 0U;
        }
    }

    /* Clear the currently loaded working copy as well. Degree_Proccess()
     * reloads the L context immediately after maintenance. */
    memset(g_tracks, 0, sizeof(g_tracks));
    g_slot_track_id[0] = 0U;
    g_slot_track_id[1] = 0U;
    memset((void *)&g_last_doa, 0, sizeof(g_last_doa));

    g_hold_az_l = 0.0f;
    g_hold_el_l = 0.0f;
    g_hold_az_r = 0.0f;
    g_hold_el_r = 0.0f;
    g_hold_valid_l = 0U;
    g_hold_valid_r = 0U;

    g_smooth_init = 0U;
    g_az_sin = 0.0f;
    g_az_cos = 1.0f;
    g_el_smooth = 0.0f;

    g_second_el_track_valid = 0U;
    g_second_el_track_deg = 0.0f;
    g_second_el_track_score = 0.0f;
    g_second_el_conf_ratio = 999.0f;
    g_second_el_conf_ok = 1U;
    g_second_force_el_snap = 1U;

    g_latest_tracks_valid = 0U;
    g_doa_silence_track_reset_count++;
}

/*
 * 양쪽 모두 inactive 상태가 일정 시간 지속되면 다음 소리 이벤트를 받을 수 있게 reset.
 */
static void DOA_FirstSoundMaintenance(uint8_t any_audio_present)
{
    uint32_t now = HAL_GetTick();
    /*
     * Motor re-latching is based on true audio silence, not BF/track state.
     * Keep the current first-sound target while either board still reports
     * audio present.  Only 1.5 s of continuous silence arms the next update.
     */
    if (any_audio_present != 0U) {
        s_first_no_active_since_ms = 0U;
        return;
    }
    if ((s_first_selected_valid == 0U) &&
        (s_first_candidate[AUDIO_STREAM_L].valid == 0U) &&
        (s_first_candidate[AUDIO_STREAM_R].valid == 0U) &&
        (g_first_sound_motor_target.valid == 0U)) {
        s_first_no_active_since_ms = 0U;
        return;
    }
    if (s_first_no_active_since_ms == 0U) {
        s_first_no_active_since_ms = now;
        return;
    }
    if ((now - s_first_no_active_since_ms) >= FIRST_SOUND_LOST_TIMEOUT_MS) {
        /*
         * 1.5 s of continuous real silence is the single event boundary for
         * BOTH motor re-latch and DOA tracking. Remove every stale azimuth
         * before arming the next utterance.
         */
        DOA_ResetTrackingAfterLongSilence();
        g_doa_led_raw_active_stream[AUDIO_STREAM_L] = 0U;
        g_doa_led_raw_active_stream[AUDIO_STREAM_R] = 0U;
        LED_L_Init();
//        LED_R_Init();
        DOA_ResetFirstSoundMotorTarget();
    }
}
uint8_t DOA_GetFirstSoundMotorTarget(doa_first_sound_target_t *out)
{
    if ((out == NULL) || (g_first_sound_motor_target.valid == 0U)) {
        return 0U;
    }
    *out = g_first_sound_motor_target;
    return 1U;
}
void DOA_ResetFirstSoundMotorTarget(void)
{
    memset((void *)s_first_candidate, 0, sizeof(s_first_candidate));
    memset((void *)s_first_prev_present, 0, sizeof(s_first_prev_present));
    s_first_selected_valid = 0U;
    s_first_selected_stream = AUDIO_STREAM_L;
    s_first_selected_seq = 0U;
    s_first_selected_sample_index = 0U;
    s_first_selected_rms = 0U;
    s_first_no_active_since_ms = 0U;
    memset((void *)&g_first_sound_motor_target, 0, sizeof(g_first_sound_motor_target));
}
