#define DOA_PROCESS_DECIM_HOPS   1U   /* 4 hops = 약 64 ms마다 SRP-PHAT 실행 */
#define DOA_COPY_RETRY_MAX       3U
static uint32_t s_doa_last_slot_seq[SHARED_SLOT_COUNT] = {0U, 0U};
static uint32_t s_doa_next_slot = SHARED_SLOT_HALF;
volatile uint32_t g_doa_input_hops = 0U;
volatile uint32_t g_doa_srp_runs = 0U;
volatile uint32_t g_doa_shared_retry = 0U;
volatile uint32_t g_doa_shared_drop = 0U;
static void DOA_ContextInit(doa_stream_context_t *ctx)
{
    memset(ctx, 0, sizeof(*ctx));
    ctx->next_slot = SHARED_SLOT_HALF;
    ctx->az_cos = 1.0f;
    ctx->second_el_conf_ratio = 999.0f;
    ctx->second_el_conf_ok = 1U;
    ctx->second_force_el_snap = 1U;
    ctx->next_track_id = 1U;
    ctx->next_born_seq = 1U;
    /* Adaptive RMS gate initial state */
    ctx->rms_noise_floor = RMS_NOISE_FLOOR_INIT;
    ctx->rms_on_threshold = fmaxf(RMS_NOISE_FLOOR_INIT * RMS_ON_RATIO, RMS_ON_MIN);
    ctx->rms_off_threshold = fmaxf(RMS_NOISE_FLOOR_INIT * RMS_OFF_RATIO, RMS_OFF_MIN);
    ctx->rms_on_count = 0U;
    ctx->rms_off_count = 0U;
}
static void DOA_LoadContext(uint32_t stream_id)
{
    doa_stream_context_t *ctx = &g_doa_ctx[stream_id];
    g_doa_active_stream = stream_id;
    memcpy(s_doa_last_slot_seq, ctx->last_slot_seq, sizeof(s_doa_last_slot_seq));
    s_doa_next_slot = ctx->next_slot;
    g_warm_hops = ctx->warm_hops;
    g_hop_consumed_cnt = ctx->hop_consumed_cnt;
    doa_decim = ctx->doa_decim;
    g_last_rms = ctx->last_rms;
    g_silence_hops = ctx->silence_hops;
    g_audio_present_state = ctx->audio_present_state;
    g_last_doa = ctx->last_doa;
    memcpy(g_frame_i16, ctx->frame_i16, sizeof(g_frame_i16));
    g_smooth_init = ctx->smooth_init;
    g_az_sin = ctx->az_sin;
    g_az_cos = ctx->az_cos;
    g_el_smooth = ctx->el_smooth;
    g_second_el_track_valid = ctx->second_el_track_valid;
    g_second_el_track_deg = ctx->second_el_track_deg;
    g_second_el_track_score = ctx->second_el_track_score;
    g_second_el_conf_ratio = ctx->second_el_conf_ratio;
    g_second_el_conf_ok = ctx->second_el_conf_ok;
    g_second_force_el_snap = ctx->second_force_el_snap;
    memcpy(g_tracks, ctx->tracks, sizeof(g_tracks));
    g_next_track_id = ctx->next_track_id;
    g_next_born_seq = ctx->next_born_seq;
    g_slot_track_id[0] = ctx->slot_track_id[0];
    g_slot_track_id[1] = ctx->slot_track_id[1];
    g_hold_az_l = ctx->hold_az_l;
    g_hold_el_l = ctx->hold_el_l;
    g_hold_az_r = ctx->hold_az_r;
    g_hold_el_r = ctx->hold_el_r;
    g_hold_valid_l = ctx->hold_valid_l;
    g_hold_valid_r = ctx->hold_valid_r;
    s_doa_uart_debug_decim_count = ctx->uart_debug_decim_count;
    if (stream_id < DOA_MAX_SOURCES)
    {
        g_doa_audio_present_stream[stream_id] = (uint32_t)ctx->audio_present_state;
        g_doa_last_rms_stream[stream_id] = ctx->last_rms;
        g_doa_silence_hops_stream[stream_id] = ctx->silence_hops;
    }
}
static void DOA_SaveContext(uint32_t stream_id)
{
    doa_stream_context_t *ctx = &g_doa_ctx[stream_id];
    memcpy(ctx->last_slot_seq, s_doa_last_slot_seq, sizeof(ctx->last_slot_seq));
    ctx->next_slot = s_doa_next_slot;
    ctx->warm_hops = g_warm_hops;
    ctx->hop_consumed_cnt = g_hop_consumed_cnt;
    ctx->doa_decim = doa_decim;
    ctx->last_rms = g_last_rms;
    ctx->silence_hops = g_silence_hops;
    ctx->audio_present_state = g_audio_present_state;
    ctx->last_doa = g_last_doa;
    memcpy(ctx->frame_i16, g_frame_i16, sizeof(ctx->frame_i16));
    ctx->smooth_init = g_smooth_init;
    ctx->az_sin = g_az_sin;
    ctx->az_cos = g_az_cos;
    ctx->el_smooth = g_el_smooth;
    ctx->second_el_track_valid = g_second_el_track_valid;
    ctx->second_el_track_deg = g_second_el_track_deg;
    ctx->second_el_track_score = g_second_el_track_score;
    ctx->second_el_conf_ratio = g_second_el_conf_ratio;
    ctx->second_el_conf_ok = g_second_el_conf_ok;
    ctx->second_force_el_snap = g_second_force_el_snap;
    memcpy(ctx->tracks, g_tracks, sizeof(ctx->tracks));
    ctx->next_track_id = g_next_track_id;
    ctx->next_born_seq = g_next_born_seq;
    ctx->slot_track_id[0] = g_slot_track_id[0];
    ctx->slot_track_id[1] = g_slot_track_id[1];
    ctx->hold_az_l = g_hold_az_l;
    ctx->hold_el_l = g_hold_el_l;
    ctx->hold_az_r = g_hold_az_r;
    ctx->hold_el_r = g_hold_el_r;
    ctx->hold_valid_l = g_hold_valid_l;
    ctx->hold_valid_r = g_hold_valid_r;
    ctx->uart_debug_decim_count = s_doa_uart_debug_decim_count;
}
static void DOA_InvalidateDCacheRange(const void *addr, uint32_t size)
{
    uintptr_t start = ((uintptr_t)addr) & ~(uintptr_t)31U;
    uintptr_t end   = (((uintptr_t)addr) + size + 31U) & ~(uintptr_t)31U;
    SCB_InvalidateDCache_by_Addr((uint32_t *)start,
                                 (int32_t)(end - start));
}
static uint32_t DOA_GetActiveStreamMask(void)
{
    DOA_InvalidateDCacheRange((const void *)&g_shared_audio.active_stream_mask,
                              sizeof(g_shared_audio.active_stream_mask) + sizeof(g_shared_audio.config_seq));
    return g_shared_audio.active_stream_mask & AUDIO_STREAM_MASK_ALL;
}
static uint8_t DOA_IsStreamActive(uint32_t stream_id)
{
    if (stream_id >= AUDIO_STREAM_COUNT)
    {
        return 0U;
    }
    return AUDIO_STREAM_MASK_HAS(DOA_GetActiveStreamMask(), stream_id) ? 1U : 0U;
}
static uint32_t DOA_SharedSlotOffset(uint32_t slot)
{
    if (slot == SHARED_SLOT_HALF)
    {
        return SHARED_HALF_OFFSET;
    }
    return SHARED_FULL_OFFSET;
}
static uint8_t DOA_CopySharedSlotToLocal(uint32_t stream_id,
                                         uint32_t slot,
                                         int16_t *dst_hop,
                                         uint32_t *out_seq)
{
    uint32_t offset;
    uint32_t guard_before;
    uint32_t guard_after;
    uint32_t seq_before;
    uint32_t seq_after;
    volatile shared_audio_stream_t *stream;
    if ((dst_hop == NULL) ||
        (slot >= SHARED_SLOT_COUNT) ||
        (stream_id >= AUDIO_STREAM_COUNT))
    {
        return 0U;
    }
    offset = DOA_SharedSlotOffset(slot);
    stream = &g_shared_audio.stream[stream_id];
    for (uint32_t retry = 0U; retry < DOA_COPY_RETRY_MAX; retry++)
    {
        DOA_InvalidateDCacheRange((const void *)stream, sizeof(*stream));
        guard_before = stream->slot_guard[slot];
        seq_before   = stream->slot_seq[slot];
        /*
         * DOA 입장에서 아직 새 PCM 없음.
         * BF의 last_slot_seq와는 별개로 관리한다.
         */
        if (seq_before == s_doa_last_slot_seq[slot])
        {
            return 0U;
        }
        /*
         * CM4가 이 slot을 쓰는 중이면 이번 loop에서는 피한다.
         */
        if ((guard_before & 1U) != 0U)
        {
            g_doa_shared_retry++;
            continue;
        }
        /*
         * shared raw TDM4CH PCM -> DOA local hop
         * uint16_t / int16_t는 bit pattern만 복사하면 되므로 memcpy 사용.
         */
        memcpy(dst_hop,
               (const void *)&stream->samples[offset],
               sizeof(int16_t) * SHARED_HOP_WORDS);
        __DMB();
        DOA_InvalidateDCacheRange((const void *)stream, sizeof(*stream));
        guard_after = stream->slot_guard[slot];
        seq_after   = stream->slot_seq[slot];
        /*
         * 복사 중 CM4가 같은 slot을 덮어쓰지 않았는지 확인.
         */
        if ((guard_before == guard_after) &&
            ((guard_after & 1U) == 0U) &&
            (seq_before == seq_after))
        {
            s_doa_last_slot_seq[slot] = seq_before;
            if (out_seq != NULL)
            {
                *out_seq = seq_before;
            }
            return 1U;
        }
        g_doa_shared_retry++;
    }
    g_doa_shared_drop++;
    return 0U;
}
static uint8_t DOA_ReadNextHop(uint32_t stream_id,
                               int16_t *dst_hop,
                               uint32_t *out_slot,
                               uint32_t *out_seq)
{
    uint32_t slot = s_doa_next_slot;
    uint32_t seq = 0U;
    /*
     * half -> full -> half -> full 순서로 우선 처리.
     */
    if (DOA_CopySharedSlotToLocal(stream_id, slot, dst_hop, &seq) != 0U)
    {
        s_doa_next_slot =
            (slot == SHARED_SLOT_HALF) ? SHARED_SLOT_FULL : SHARED_SLOT_HALF;
        if (out_slot != NULL)
        {
            *out_slot = slot;
        }
        if (out_seq != NULL)
        {
            *out_seq = seq;
        }
        return 1U;
    }
    /*
     * 예상 slot에 새 데이터가 없으면 반대 slot도 한 번 확인.
     * DOA가 느려서 hop을 놓친 경우 최신 slot을 따라가기 위함.
     */
    slot = (slot == SHARED_SLOT_HALF) ? SHARED_SLOT_FULL : SHARED_SLOT_HALF;
    if (DOA_CopySharedSlotToLocal(stream_id, slot, dst_hop, &seq) != 0U)
    {
        s_doa_next_slot =
            (slot == SHARED_SLOT_HALF) ? SHARED_SLOT_FULL : SHARED_SLOT_HALF;
        if (out_slot != NULL)
        {
            *out_slot = slot;
        }
        if (out_seq != NULL)
        {
            *out_seq = seq;
        }
        return 1U;
    }
    return 0U;
}
/* =========================================================
 * Hold / slot helpers
 * ========================================================= */
static void set_hold_from_slot_result(int slot, float az_deg, float el_deg)
{
    if (slot == 0) {
        g_hold_az_l = az_deg;
        g_hold_el_l = el_deg;
        g_hold_valid_l = 1;
    } else {
        g_hold_az_r = az_deg;
        g_hold_el_r = el_deg;
        g_hold_valid_r = 1;
    }
}
static void get_hold_for_slot(int slot, float *az_deg, float *el_deg, uint8_t *valid)
{
    if (slot == 0) {
        if (az_deg) *az_deg = g_hold_az_l;
        if (el_deg) *el_deg = g_hold_el_l;
        if (valid)  *valid  = g_hold_valid_l;
    } else {
        if (az_deg) *az_deg = g_hold_az_r;
        if (el_deg) *el_deg = g_hold_el_r;
        if (valid)  *valid  = g_hold_valid_r;
    }
}
/* =========================================================
 * DOA smoothing
 * ========================================================= */
static void smooth_doa(doa_result_t *r)
{
#if (DOA_SMOOTH_ENABLE)
    float a = DOA_SMOOTH_ALPHA;
    if (!g_smooth_init) {
        float az = r->az_deg * (PI / 180.0f);
        g_az_sin = arm_sin_f32(az);
        g_az_cos = arm_cos_f32(az);
        g_el_smooth = r->el_deg;
        g_smooth_init = 1;
    } else {
        float az = r->az_deg * (PI / 180.0f);
        float s = arm_sin_f32(az);
        float c = arm_cos_f32(az);
        g_az_sin = (1.0f - a) * g_az_sin + a * s;
        g_az_cos = (1.0f - a) * g_az_cos + a * c;
        g_el_smooth = (1.0f - a) * g_el_smooth + a * r->el_deg;
    }
    float norm;
    arm_sqrt_f32(g_az_sin * g_az_sin + g_az_cos * g_az_cos, &norm);
    if (norm > 1e-6f) {
        g_az_sin /= norm;
        g_az_cos /= norm;
    }
    float az_out = atan2f(g_az_sin, g_az_cos) * (180.0f / PI);
    if (az_out < 0.0f) az_out += 360.0f;
    r->az_deg = az_out;
    r->el_deg = g_el_smooth;
#endif
}
/* =========================================================
 * Init
 * ========================================================= */
static void tracks_reset(void)
{
    memset(g_tracks, 0, sizeof(g_tracks));
    g_next_track_id = 1;
    g_next_born_seq = 1;
    g_slot_track_id[0] = 0;
    g_slot_track_id[1] = 0;
}
void doa_init(void)
{
    arm_rfft_fast_init_f32(&g_rfft, NFFT);
    memset(g_srp_noise_psd, 0, sizeof(g_srp_noise_psd));
    memset(g_srp_noise_learn_frames, 0, sizeof(g_srp_noise_learn_frames));
#if (SRP_USE_COHERENCE_WEIGHT != 0)
    memset(g_srp_coh_auto, 0, sizeof(g_srp_coh_auto));
    memset(g_srp_coh_cross_re, 0, sizeof(g_srp_coh_cross_re));
    memset(g_srp_coh_cross_im, 0, sizeof(g_srp_coh_cross_im));
    memset(g_srp_coh_frames, 0, sizeof(g_srp_coh_frames));
#endif
    g_srp_frame_valid = 1U;
    g_srp_dbg_rejected_frames = 0U;
    for (int n = 0; n < FRAME_SIZE; n++) {
        g_win[n] = 0.5f - 0.5f * arm_cos_f32(2.0f * PI * (float)n / (float)(FRAME_SIZE - 1));
    }
    float maxdist = 0.0f;
    for (int p = 0; p < NPAIR; p++) {
        uint8_t i = g_pairs[p].i;
        uint8_t j = g_pairs[p].j;
        float dx = g_mic_pos[i][0] - g_mic_pos[j][0];
        float dy = g_mic_pos[i][1] - g_mic_pos[j][1];
        float dz = g_mic_pos[i][2] - g_mic_pos[j][2];
        g_rij[p][0] = dx;
        g_rij[p][1] = dy;
        g_rij[p][2] = dz;
        float d2 = dx*dx + dy*dy + dz*dz;
        if (d2 < 1e-9f) d2 = 1e-9f;
#if USE_BASELINE2_WEIGHT
        g_wpair[p] = d2;
#else
        g_wpair[p] = 1.0f;
#endif
        float d;
        arm_sqrt_f32(d2, &d);
        if (d > maxdist) maxdist = d;
    }
    {
        float max_tau = maxdist / SPEED_OF_SOUND;
        g_maxlag_samp = (int)ceilf(max_tau * FS) + 1;
        if (g_maxlag_samp > (NFFT / 2 - 1)) g_maxlag_samp = (NFFT / 2 - 1);
    }
    memset((void *)g_latest_tracks, 0, sizeof(g_latest_tracks));
    g_latest_tracks_seq = 0U;
    g_latest_tracks_valid = 0U;
    for (uint32_t stream = 0U; stream < AUDIO_STREAM_COUNT; stream++)
    {
        DOA_ContextInit(&g_doa_ctx[stream]);
    }
    DOA_LoadContext(AUDIO_STREAM_L);
}
/* =========================================================
 * Front-end
 * ========================================================= */
static void compute_channel_fft(const int16_t *in_i16_interleaved)
{
    for (int n = 0; n < FRAME_SIZE; n++) {
        for (int m = 0; m < NMIC; m++) {
            int16_t s = in_i16_interleaved[n * NMIC + m];
            x_t[m][n] = ((float)s) * (1.0f / 32768.0f) * g_win[n];
        }
    }
    for (int m = 0; m < NMIC; m++) {
        arm_rfft_fast_f32(&g_rfft, x_t[m], X_packed[m], 0);
        rfft_unpack_bins(X_packed[m], Xc[m]);
    }
}
/* =========================================================
 * SRP root-cause test helpers
 * ========================================================= */
static float srp_linear_weight(float x, float x0, float x1)
{
    if (x <= x0) return 0.0f;
    if (x >= x1) return 1.0f;
    return (x - x0) / (x1 - x0);
}
static void SRP_UpdateSpectralNoiseModel(const int16_t *frame_interleaved_4ch,
                                         uint32_t stream_id)
{
#if (SRP_USE_BIN_SNR_GATE != 0)
    if ((frame_interleaved_4ch == NULL) || (stream_id >= AUDIO_STREAM_COUNT)) return;
    compute_channel_fft(frame_interleaved_4ch);
    const float a = SRP_NOISE_EMA_NEW;
    uint32_t nframe = g_srp_noise_learn_frames[stream_id];
    for (int m = 0; m < NMIC; m++) {
        for (int k = 1; k < NBINS - 1; k++) {
            float re = Xc[m][k][0];
            float im = Xc[m][k][1];
            float pwr = re * re + im * im;
            if (nframe == 0U) {
                g_srp_noise_psd[stream_id][m][k] = pwr + EPS_PHAT;
            } else {
                g_srp_noise_psd[stream_id][m][k] =
                    (1.0f - a) * g_srp_noise_psd[stream_id][m][k] + a * pwr;
            }
        }
    }
    if (g_srp_noise_learn_frames[stream_id] < 0xFFFFFFFFU) {
        g_srp_noise_learn_frames[stream_id]++;
    }
    g_srp_dbg_noise_learn_frames = g_srp_noise_learn_frames[stream_id];
#else
    (void)frame_interleaved_4ch;
    (void)stream_id;
#endif
}
#if (SRP_USE_COHERENCE_WEIGHT != 0)
static void SRP_ResetCoherenceStream(uint32_t stream_id)
{
    if (stream_id >= AUDIO_STREAM_COUNT) return;
    memset(g_srp_coh_auto[stream_id], 0, sizeof(g_srp_coh_auto[stream_id]));
    memset(g_srp_coh_cross_re[stream_id], 0, sizeof(g_srp_coh_cross_re[stream_id]));
    memset(g_srp_coh_cross_im[stream_id], 0, sizeof(g_srp_coh_cross_im[stream_id]));
    g_srp_coh_frames[stream_id] = 0U;
    g_srp_dbg_coh_frames = 0U;
}
static void SRP_UpdateCoherenceStatsFromXc(uint32_t stream_id)
{
    if (stream_id >= AUDIO_STREAM_COUNT) return;
    const float a = SRP_COH_EMA_NEW;
    uint32_t nframe = g_srp_coh_frames[stream_id];
    for (int m = 0; m < NMIC; m++) {
        for (int k = 1; k < NBINS - 1; k++) {
            float re = Xc[m][k][0];
            float im = Xc[m][k][1];
            float pwr = re * re + im * im;
            if (nframe == 0U) g_srp_coh_auto[stream_id][m][k] = pwr + EPS_PHAT;
            else g_srp_coh_auto[stream_id][m][k] =
                (1.0f - a) * g_srp_coh_auto[stream_id][m][k] + a * pwr;
        }
    }
    for (int p = 0; p < NPAIR; p++) {
        uint8_t i = g_pairs[p].i;
        uint8_t j = g_pairs[p].j;
        for (int k = 1; k < NBINS - 1; k++) {
            float Xi_re = Xc[i][k][0];
            float Xi_im = Xc[i][k][1];
            float Xj_re = Xc[j][k][0];
            float Xj_im = Xc[j][k][1];
            float re = Xi_re * Xj_re + Xi_im * Xj_im;
            float im = Xi_im * Xj_re - Xi_re * Xj_im;
            if (nframe == 0U) {
                g_srp_coh_cross_re[stream_id][p][k] = re;
                g_srp_coh_cross_im[stream_id][p][k] = im;
            } else {
                g_srp_coh_cross_re[stream_id][p][k] =
                    (1.0f - a) * g_srp_coh_cross_re[stream_id][p][k] + a * re;
                g_srp_coh_cross_im[stream_id][p][k] =
                    (1.0f - a) * g_srp_coh_cross_im[stream_id][p][k] + a * im;
            }
        }
    }
    if (g_srp_coh_frames[stream_id] < 0xFFFFFFFFU) g_srp_coh_frames[stream_id]++;
    g_srp_dbg_coh_frames = g_srp_coh_frames[stream_id];
}
#endif
static float SRP_GetBinSnrWeight(uint32_t stream_id, int p, int k, float *out_ratio)
{
#if (SRP_USE_BIN_SNR_GATE != 0)
    if ((stream_id >= AUDIO_STREAM_COUNT) ||
        (g_srp_noise_learn_frames[stream_id] < SRP_NOISE_MIN_LEARN_FRAMES)) {
        if (out_ratio) *out_ratio = 999.0f;
        return 1.0f;
    }
    uint8_t i = g_pairs[p].i;
    uint8_t j = g_pairs[p].j;
    float pi = Xc[i][k][0] * Xc[i][k][0] + Xc[i][k][1] * Xc[i][k][1];
    float pj = Xc[j][k][0] * Xc[j][k][0] + Xc[j][k][1] * Xc[j][k][1];
    float ni = g_srp_noise_psd[stream_id][i][k] + EPS_PHAT;
    float nj = g_srp_noise_psd[stream_id][j][k] + EPS_PHAT;
    float ri = pi / ni;
    float rj = pj / nj;
    float ratio = fminf(ri, rj);
    if (out_ratio) *out_ratio = ratio;
    return srp_linear_weight(ratio, SRP_BIN_SNR_RATIO_ZERO, SRP_BIN_SNR_RATIO_FULL);
#else
    (void)stream_id; (void)p; (void)k;
    if (out_ratio) *out_ratio = 999.0f;
    return 1.0f;
#endif
}
static float SRP_GetBinCoherenceWeight(uint32_t stream_id, int p, int k, float *out_coh)
{
#if (SRP_USE_COHERENCE_WEIGHT != 0)
    if ((stream_id >= AUDIO_STREAM_COUNT) ||
        (g_srp_coh_frames[stream_id] < SRP_COH_MIN_FRAMES)) {
        if (out_coh) *out_coh = 1.0f;
        return 1.0f;
    }
    uint8_t i = g_pairs[p].i;
    uint8_t j = g_pairs[p].j;
    float cr = g_srp_coh_cross_re[stream_id][p][k];
    float ci = g_srp_coh_cross_im[stream_id][p][k];
    float num = cr * cr + ci * ci;
    float den = g_srp_coh_auto[stream_id][i][k] * g_srp_coh_auto[stream_id][j][k] + EPS_PHAT;
    float coh = clampf(num / den, 0.0f, 1.0f);
    if (out_coh) *out_coh = coh;
    return srp_linear_weight(coh, SRP_COH_ZERO, SRP_COH_FULL);
#else
    (void)stream_id; (void)p; (void)k;
    if (out_coh) *out_coh = 1.0f;
    return 1.0f;
#endif
}
#if (SRP_USE_SUBBAND_VOTING != 0)
static void SRP_BuildSubbandGcc(void)
{
    const float df = FS / (float)NFFT;
    const float fmin[SRP_SUBBAND_COUNT] = {
        SRP_SUBBAND0_FMIN_HZ, SRP_SUBBAND1_FMIN_HZ, SRP_SUBBAND2_FMIN_HZ
    };
    const float fmax[SRP_SUBBAND_COUNT] = {
        SRP_SUBBAND0_FMAX_HZ, SRP_SUBBAND1_FMAX_HZ, SRP_SUBBAND2_FMAX_HZ
    };
    for (int b = 0; b < SRP_SUBBAND_COUNT; b++) {
        int k0 = (int)(fmin[b] / df);
        int k1 = (int)(fmax[b] / df);
        if (k0 < 1) k0 = 1;
        if (k1 > NBINS - 2) k1 = NBINS - 2;
        for (int p = 0; p < NPAIR; p++) {
            memset(g_srp_subband_bins_tmp, 0, sizeof(g_srp_subband_bins_tmp));
            for (int k = k0; k <= k1; k++) {
                g_srp_subband_bins_tmp[k][0] = Gphat_bins[p][k][0];
                g_srp_subband_bins_tmp[k][1] = Gphat_bins[p][k][1];
            }
            bins_pack_rfft(g_srp_subband_bins_tmp, g_srp_subband_packed_tmp);
            arm_rfft_fast_f32(&g_rfft, g_srp_subband_packed_tmp, g_srp_subband_gcc[b][p], 1);
        }
    }
}
#endif
/* =========================================================
 * GCC-PHAT
 * ========================================================= */
static void compute_gcc_phat_from_Xc(void)
{
    const float df = FS / (float)NFFT;
    int k0 = (int)(SRP_FMIN_HZ / df);
    int k1 = (int)(SRP_FMAX_HZ / df);
    uint32_t stream_id = g_doa_active_stream;
    uint32_t used_bins = 0U;
    uint32_t rejected_bins = 0U;
    float sum_snr_w = 0.0f;
    float sum_coh = 0.0f;
    uint32_t weight_samples = 0U;
    if (k0 < 1) k0 = 1;
    if (k1 > (NBINS - 2)) k1 = (NBINS - 2);
    if (k1 < k0) { k0 = 1; k1 = NBINS - 2; }
#if (SRP_USE_COHERENCE_WEIGHT != 0)
    SRP_UpdateCoherenceStatsFromXc(stream_id);
#endif
    for (int k = 0; k < NBINS; k++) {
        g_srp_dbg_bin_snr[k] = 0.0f;
        g_srp_dbg_bin_coherence[k] = 0.0f;
        g_srp_dbg_bin_weight[k] = 0.0f;
    }
    for (int p = 0; p < NPAIR; p++) {
        uint8_t i = g_pairs[p].i;
        uint8_t j = g_pairs[p].j;
        Gphat_bins[p][0][0] = 0.0f;
        Gphat_bins[p][0][1] = 0.0f;
        Gphat_bins[p][NBINS - 1][0] = 0.0f;
        Gphat_bins[p][NBINS - 1][1] = 0.0f;
        for (int k = 1; k < NBINS - 1; k++) {
            if (k < k0 || k > k1) {
                Gphat_bins[p][k][0] = 0.0f;
                Gphat_bins[p][k][1] = 0.0f;
                continue;
            }
            float Xi_re = Xc[i][k][0];
            float Xi_im = Xc[i][k][1];
            float Xj_re = Xc[j][k][0];
            float Xj_im = Xc[j][k][1];
            float G_re = Xi_re * Xj_re + Xi_im * Xj_im;
            float G_im = Xi_im * Xj_re - Xi_re * Xj_im;
            float mag2 = G_re * G_re + G_im * G_im;
            float mag, denom;
            float snr_ratio = 999.0f;
            float coh = 1.0f;
            float snr_w = SRP_GetBinSnrWeight(stream_id, p, k, &snr_ratio);
            float coh_w = SRP_GetBinCoherenceWeight(stream_id, p, k, &coh);
            float reliability = snr_w * coh_w;
            arm_sqrt_f32(mag2, &mag);
#if (PHAT_MODE == PHAT_MODE_FULL)
            denom = mag + EPS_PHAT;
#elif (PHAT_MODE == PHAT_MODE_SOFT05)
            arm_sqrt_f32(mag + EPS_PHAT, &denom);
#else
            denom = mag + EPS_PHAT;
#endif
            if (reliability <= 0.0f) {
                Gphat_bins[p][k][0] = 0.0f;
                Gphat_bins[p][k][1] = 0.0f;
                rejected_bins++;
            } else {
                Gphat_bins[p][k][0] = reliability * (G_re / denom);
                Gphat_bins[p][k][1] = reliability * (G_im / denom);
                used_bins++;
            }
            sum_snr_w += snr_w;
            sum_coh += coh;
            weight_samples++;
            if ((uint32_t)p == SRP_DEBUG_PAIR_INDEX) {
                g_srp_dbg_bin_snr[k] = snr_ratio;
                g_srp_dbg_bin_coherence[k] = coh;
                g_srp_dbg_bin_weight[k] = reliability;
            }
        }
    }
    g_srp_dbg_used_bins = used_bins;
    g_srp_dbg_rejected_bins = rejected_bins;
    g_srp_dbg_mean_snr_weight = (weight_samples > 0U) ? (sum_snr_w / (float)weight_samples) : 0.0f;
    g_srp_dbg_mean_coherence = (weight_samples > 0U) ? (sum_coh / (float)weight_samples) : 0.0f;
    if (stream_id < AUDIO_STREAM_COUNT) {
        g_srp_dbg_noise_learn_frames = g_srp_noise_learn_frames[stream_id];
#if (SRP_USE_COHERENCE_WEIGHT != 0)
        g_srp_dbg_coh_frames = g_srp_coh_frames[stream_id];
#else
        g_srp_dbg_coh_frames = 0U;
#endif
    }
    for (int p = 0; p < NPAIR; p++) {
        bins_pack_rfft(Gphat_bins[p], Gphat_packed[p]);
        arm_rfft_fast_f32(&g_rfft, Gphat_packed[p], gcc_time[p], 1);
    }
#if (SRP_USE_SUBBAND_VOTING != 0)
    SRP_BuildSubbandGcc();
#endif
}
static void compute_gcc_phat_time(const int16_t *in_i16_interleaved)
{
    compute_channel_fft(in_i16_interleaved);
    compute_gcc_phat_from_Xc();
}
/* =========================================================
 * GCC helpers
 * ========================================================= */
static inline float gcc_at_lag_interp(const float *gcc, float lag_f)
{
    if (lag_f > (float)(NFFT/2 - 2)) lag_f = (float)(NFFT/2 - 2);
    if (lag_f < (float)(-NFFT/2 + 2)) lag_f = (float)(-NFFT/2 + 2);
    int lag0 = (int)floorf(lag_f);
    float frac = lag_f - (float)lag0;
    int idx0 = (lag0 >= 0) ? lag0 : (NFFT + lag0);
    int idx1 = idx0 + 1;
    if (idx1 >= NFFT) idx1 -= NFFT;
    float y0 = gcc[idx0];
    float y1 = gcc[idx1];
    return y0 + frac * (y1 - y0);
}
/* =========================================================
 * Second-code elevation estimator
 * ========================================================= */
static float second_elevation_srp_score_at(float az_deg, float el_deg)
{
    float u[3];
    unitvec_from_az_el(az_deg, el_deg, u);
    float score = 0.0f;
    for (int p = 0; p < NPAIR; p++) {
        float tau = dot3(g_rij[p], u) / SPEED_OF_SOUND;
        float lag_f = tau * FS;
        lag_f = clampf(lag_f,
                       (float)(-g_maxlag_samp),
                       (float)g_maxlag_samp);
        score += g_wpair[p] * gcc_at_lag_interp(gcc_time[p], lag_f);
    }
    return score;
}
static lag_peak_t second_gcc_find_peak_lag_for_ls(const float *gcc)
{
    lag_peak_t peak;
    peak.lag = 0.0f;
    peak.val = -1e30f;
    peak.valid = 0U;
    int best_lag = 0;
    for (int lag = -g_maxlag_samp; lag <= g_maxlag_samp; lag++) {
        int idx = (lag >= 0) ? lag : (NFFT + lag);
        float v = gcc[idx];
        if (v > peak.val) {
            peak.val = v;
            best_lag = lag;
            peak.valid = 1U;
        }
    }
    if (peak.valid == 0U) {
        return peak;
    }
    {
        int im = best_lag - 1;
        int ip = best_lag + 1;
        if (im < -NFFT / 2 + 1) im = best_lag;
        if (ip >  NFFT / 2 - 1) ip = best_lag;
        int idx_m = (im >= 0) ? im : (NFFT + im);
        int idx_0 = (best_lag >= 0) ? best_lag : (NFFT + best_lag);
        int idx_p = (ip >= 0) ? ip : (NFFT + ip);
        float ym = gcc[idx_m];
        float y0 = gcc[idx_0];
        float yp = gcc[idx_p];
        float den = ym - 2.0f * y0 + yp;
        float delta = 0.0f;
        if (fabsf(den) > 1e-12f) {
            delta = 0.5f * (ym - yp) / den;
            delta = clampf(delta, -0.5f, 0.5f);
        }
        peak.lag = (float)best_lag + delta;
        peak.val = y0 - 0.25f * (ym - yp) * delta;
    }
    return peak;
}
static float estimate_elevation_tdoa_ls_follow_az_from_second_code(float az_deg)
{
    float az = wrap_deg_360(az_deg) * (PI / 180.0f);
    float caz = arm_cos_f32(az);
    float saz = arm_sin_f32(az);
    float num = 0.0f;
    float den = 0.0f;
    for (int p = 0; p < NPAIR; p++) {
        float dx = g_rij[p][0];
        float dy = g_rij[p][1];
        lag_peak_t pk = second_gcc_find_peak_lag_for_ls(gcc_time[p]);
        if (pk.valid == 0U) {
            continue;
        }
        float tau = pk.lag / FS;
        float q = dx * caz + dy * saz;
        num += q * tau;
        den += q * q;
    }
    if (den < 1e-10f) {
        return g_second_el_track_valid ? g_second_el_track_deg : 0.0f;
    }
    float cel = SPEED_OF_SOUND * num / den;
    /* Planar upper-hemisphere policy from the second code. */
    cel = clampf(cel, 0.0f, 1.0f);
    float el = acosf(cel) * (180.0f / PI);
    el = clampf(el,
                (float)SECOND_TDOA_LS_EL_MIN_DEG,
                (float)SECOND_TDOA_LS_EL_MAX_DEG);
    if ((g_second_el_track_valid == 0U) ||
        (g_second_force_el_snap != 0U)) {
        g_second_el_track_valid = 1U;
        g_second_el_track_deg = el;
        g_second_el_track_score = cel;
        g_second_force_el_snap = 0U;
    } else {
        float diff = el - g_second_el_track_deg;
        float step = 0.50f * diff;
        step = clampf(step, -SECOND_EL_TURN_LOCK_MAX_STEP_DEG, SECOND_EL_TURN_LOCK_MAX_STEP_DEG);
        g_second_el_track_deg += step;
        g_second_el_track_score = 0.8f * g_second_el_track_score + 0.2f * cel;
    }
    return clampf(g_second_el_track_deg,
                  (float)SECOND_TDOA_LS_EL_MIN_DEG,
                  (float)SECOND_TDOA_LS_EL_MAX_DEG);
}
/*
 * First-code style elevation estimator.
 *
 * This keeps the second code's SRP/top2/tracking flow, but calculates elevation
 * from the same TDOA-LS idea used by the first code:
 *
 *   1) find the best GCC-PHAT lag for every mic pair
 *   2) solve A * p = tau using all pair lags, where p = [px, py]
 *   3) treat |p| * SPEED_OF_SOUND as cos(elevation)
 *   4) elevation = acos(cos(elevation))
 *
 * The LS azimuth is returned only for debug/quality information. The second
 * code's SRP-PHAT azimuth is still kept as the output azimuth.
 */
static uint8_t estimate_elevation_from_first_code_ls(float *out_el_deg,
                                                     float *out_ls_az_deg,
                                                     float *out_resid_m)
{
    float ata00 = 0.0f;
    float ata01 = 0.0f;
    float ata11 = 0.0f;
    float atb0  = 0.0f;
    float atb1  = 0.0f;
    float pair_tau[NPAIR] = {0.0f};
    uint8_t pair_valid[NPAIR] = {0U};
    uint32_t valid_pairs = 0U;
    for (int p = 0; p < NPAIR; p++) {
        float dx = g_rij[p][0];
        float dy = g_rij[p][1];
        lag_peak_t pk = second_gcc_find_peak_lag_for_ls(gcc_time[p]);
        if (pk.valid == 0U) {
            continue;
        }
        float tau = pk.lag / FS;
        pair_tau[p] = tau;
        pair_valid[p] = 1U;
        ata00 += dx * dx;
        ata01 += dx * dy;
        ata11 += dy * dy;
        atb0  += dx * tau;
        atb1  += dy * tau;
        valid_pairs++;
    }
    if (valid_pairs < 2U) {
        return 0U;
    }
    float det = ata00 * ata11 - ata01 * ata01;
    if (fabsf(det) < 1e-12f) {
        return 0U;
    }
    float inv00 =  ata11 / det;
    float inv01 = -ata01 / det;
    float inv11 =  ata00 / det;
    float px = inv00 * atb0 + inv01 * atb1;
    float py = inv01 * atb0 + inv11 * atb1;
    float ls_az = atan2f(py, px) * (180.0f / PI);
    if (ls_az < 0.0f) {
        ls_az += 360.0f;
    }
    float pnorm = sqrtf((px * px) + (py * py));
    float cel = SPEED_OF_SOUND * pnorm;
    cel = clampf(cel, 0.0f, 1.0f);
    float el = acosf(cel) * (180.0f / PI);
    el = clampf(el,
                (float)SECOND_TDOA_LS_EL_MIN_DEG,
                (float)SECOND_TDOA_LS_EL_MAX_DEG);
    /* Real TDOA-LS RMS fit residual in meters. */
    float err_m2_sum = 0.0f;
    uint32_t resid_pairs = 0U;
    for (int p = 0; p < NPAIR; p++) {
        if (pair_valid[p] == 0U) {
            continue;
        }
        float pred_tau = g_rij[p][0] * px + g_rij[p][1] * py;
        float err_m = SPEED_OF_SOUND * (pair_tau[p] - pred_tau);
        err_m2_sum += err_m * err_m;
        resid_pairs++;
    }
    if (resid_pairs == 0U) {
        return 0U;
    }
    float resid_m = sqrtf(err_m2_sum / (float)resid_pairs);
    if (out_el_deg != NULL) {
        *out_el_deg = el;
    }
    if (out_ls_az_deg != NULL) {
        *out_ls_az_deg = ls_az;
    }
    if (out_resid_m != NULL) {
        *out_resid_m = resid_m;
    }
    return 1U;
}
static float second_elevation_srp_scan_raw(float az_deg,
                                           float *out_score,
                                           uint8_t *out_conf_ok)
{
#if SECOND_CODE_ELEVATION_ENABLE
#if SECOND_EL_SRP_SCAN_ENABLE
    int best_el_i = SECOND_EL_SRP_MIN_DEG;
    int second_el_i = SECOND_EL_SRP_MIN_DEG;
    float best_score = -1e30f;
    float second_score = -1e30f;
    for (int el = SECOND_EL_SRP_MIN_DEG;
         el <= SECOND_EL_SRP_MAX_DEG;
         el += SECOND_EL_SRP_STEP_DEG) {
        float score = second_elevation_srp_score_at(az_deg, (float)el);
        if (score > best_score) {
            if (iabs_int(el - best_el_i) >= SECOND_EL_CONF_SEP_DEG) {
                second_score = best_score;
                second_el_i = best_el_i;
            }
            best_score = score;
            best_el_i = el;
        } else if ((iabs_int(el - best_el_i) >= SECOND_EL_CONF_SEP_DEG) &&
                   (score > second_score)) {
            second_score = score;
            second_el_i = el;
        }
    }
    if (second_score < -1e20f) {
        for (int el = SECOND_EL_SRP_MIN_DEG;
             el <= SECOND_EL_SRP_MAX_DEG;
             el += SECOND_EL_SRP_STEP_DEG) {
            if (iabs_int(el - best_el_i) < SECOND_EL_CONF_SEP_DEG) {
                continue;
            }
            float score = second_elevation_srp_score_at(az_deg, (float)el);
            if (score > second_score) {
                second_score = score;
                second_el_i = el;
            }
        }
    }
    float best_el = (float)best_el_i;
#if SECOND_EL_SRP_PARABOLIC_REFINE
    if ((best_el_i > SECOND_EL_SRP_MIN_DEG) &&
        (best_el_i < SECOND_EL_SRP_MAX_DEG)) {
        float ym = second_elevation_srp_score_at(az_deg,
                                                 (float)(best_el_i - SECOND_EL_SRP_STEP_DEG));
        float y0 = best_score;
        float yp = second_elevation_srp_score_at(az_deg,
                                                 (float)(best_el_i + SECOND_EL_SRP_STEP_DEG));
        float den = ym - 2.0f * y0 + yp;
        if (fabsf(den) > 1e-12f) {
            float delta = 0.5f * (ym - yp) / den;
            delta = clampf(delta, -1.0f, 1.0f);
            best_el = (float)best_el_i + delta * (float)SECOND_EL_SRP_STEP_DEG;
        }
    }
#endif
    best_el = clampf(best_el,
                     (float)SECOND_EL_SRP_MIN_DEG,
                     (float)SECOND_EL_SRP_MAX_DEG);
    {
        float ratio = 999.0f;
        uint8_t conf_ok = 1U;
#if SECOND_EL_CONF_GATE_ENABLE
        if (second_score > SECOND_EL_CONF_ABS_MIN) {
            ratio = best_score / (second_score + 1e-12f);
        }
        if (best_score < SECOND_EL_CONF_ABS_MIN) {
            conf_ok = 0U;
        }
        if (ratio < SECOND_EL_CONF_RATIO_MIN) {
            conf_ok = 0U;
        }
#else
        (void)second_el_i;
#endif
        g_second_el_conf_ratio = ratio;
        g_second_el_conf_ok = conf_ok;
        if (out_score != NULL) {
            *out_score = best_score;
        }
        if (out_conf_ok != NULL) {
            *out_conf_ok = conf_ok;
        }
    }
    (void)second_el_i;
    return best_el;
#else
    (void)az_deg;
    if (out_score != NULL) {
        *out_score = 0.0f;
    }
    if (out_conf_ok != NULL) {
        *out_conf_ok = 0U;
    }
    return 0.0f;
#endif
#else
    (void)az_deg;
    if (out_score != NULL) {
        *out_score = 0.0f;
    }
    if (out_conf_ok != NULL) {
        *out_conf_ok = 0U;
    }
    return 0.0f;
#endif
}
static float estimate_elevation_from_second_code(float az_deg)
{
    float best_score = 0.0f;
    uint8_t conf_ok = 0U;
    float best_el = second_elevation_srp_scan_raw(az_deg, &best_score, &conf_ok);
#if SECOND_EL_CONF_GATE_ENABLE
    if ((conf_ok == 0U) &&
        (g_second_el_track_valid != 0U) &&
        (g_second_force_el_snap == 0U)) {
#if SECOND_EL_CONF_HOLD_ON_LOW
        return clampf(g_second_el_track_deg,
                      (float)SECOND_EL_SRP_MIN_DEG,
                      (float)SECOND_EL_SRP_MAX_DEG);
#endif
    }
#else
    (void)conf_ok;
#endif
    if ((g_second_el_track_valid == 0U) ||
        (g_second_force_el_snap != 0U)) {
        g_second_el_track_valid = 1U;
        g_second_el_track_deg = best_el;
        g_second_el_track_score = best_score;
        g_second_force_el_snap = 0U;
    } else {
        float diff = best_el - g_second_el_track_deg;
        if (fabsf(diff) <= SECOND_EL_SRP_DEADBAND_DEG) {
            diff = 0.0f;
        }
        float step = SECOND_EL_SRP_SMOOTH_ALPHA * diff;
        step = clampf(step,
                      -SECOND_EL_TURN_LOCK_MAX_STEP_DEG,
                      SECOND_EL_TURN_LOCK_MAX_STEP_DEG);
        g_second_el_track_deg += step;
        g_second_el_track_score =
            0.8f * g_second_el_track_score + 0.2f * best_score;
    }
    return clampf(g_second_el_track_deg,
                  (float)SECOND_EL_SRP_MIN_DEG,
                  (float)SECOND_EL_SRP_MAX_DEG);
}
static void refine_top2_elevation_from_second_code(doa_cand_t top2[TOPK_DOA])
{
    for (int c = 0; c < TOPK_DOA; c++) {
        top2[c].el = 0.0f;
        top2[c].el_valid = 0U;
        top2[c].el_resid = 1e30f;
    }
#if SECOND_CODE_ELEVATION_ENABLE
    /*
     * The second attached code is a single-output elevation estimator.
     * Therefore, update the smoothed elevation state only once for top2[0].
     * Secondary candidates get a raw scan result so they do not disturb
     * the primary elevation smoother.
     */
    if (TOPK_DOA > 0) {
        float first_ls_el = 0.0f;
        float first_ls_az = 0.0f;
        float first_ls_resid_m = 0.0f;
        if (estimate_elevation_from_first_code_ls(&first_ls_el,
                                                  &first_ls_az,
                                                  &first_ls_resid_m) != 0U) {
            /*
             * Keep the second code's SRP-PHAT azimuth.
             * Replace only elevation with the first-code style TDOA-LS result.
             */
            top2[0].el = first_ls_el;
            top2[0].el_valid = 1U;
            top2[0].el_resid = first_ls_resid_m;
        }
        else {
            top2[0].el = 0.0f;
            top2[0].el_valid = 0U;
            top2[0].el_resid = 1e30f;
        }
        (void)first_ls_az;
    }
    for (int c = 1; c < TOPK_DOA; c++) {
        float raw_score = 0.0f;
        uint8_t raw_conf = 0U;
        top2[c].el = second_elevation_srp_scan_raw(top2[c].az,
                                                   &raw_score,
                                                   &raw_conf);
        top2[c].el_valid = raw_conf;
        top2[c].el_resid = raw_score;
    }
#endif
}
static inline float gcc_at_int_lag(const float *gcc, int lag)
{
    if (lag > (NFFT/2 - 1)) lag = (NFFT/2 - 1);
    if (lag < (-NFFT/2 + 1)) lag = (-NFFT/2 + 1);
    int idx = (lag >= 0) ? lag : (NFFT + lag);
    return gcc[idx];
}
static void sort_pair_peaks_desc(int p)
{
    uint8_t n = g_pair_peak_count[p];
    for (uint8_t i = 0; i < n; i++) {
        for (uint8_t j = (uint8_t)(i + 1); j < n; j++) {
            if (g_pair_peaks[p][j].val > g_pair_peaks[p][i].val) {
                lag_peak_t tmp = g_pair_peaks[p][i];
                g_pair_peaks[p][i] = g_pair_peaks[p][j];
                g_pair_peaks[p][j] = tmp;
            }
        }
    }
}
static void insert_pair_peak_sorted(int p, float lag, float val)
{
    uint8_t n = g_pair_peak_count[p];
    /* Merge near-duplicate peaks. Keep the stronger one. */
    for (uint8_t i = 0; i < n; i++) {
        if (fabsf(lag - g_pair_peaks[p][i].lag) < TDOA_PEAK_MIN_SEP_SAMP) {
            if (val > g_pair_peaks[p][i].val) {
                g_pair_peaks[p][i].lag = lag;
                g_pair_peaks[p][i].val = val;
                g_pair_peaks[p][i].valid = 1;
                sort_pair_peaks_desc(p);
            }
            return;
        }
    }
    if (n < TDOA_MAX_PEAKS_PER_PAIR) {
        g_pair_peaks[p][n].lag = lag;
        g_pair_peaks[p][n].val = val;
        g_pair_peaks[p][n].valid = 1;
        g_pair_peak_count[p] = (uint8_t)(n + 1);
        sort_pair_peaks_desc(p);
        return;
    }
    /* Replace the weakest if the new one is stronger. */
    if (val > g_pair_peaks[p][TDOA_MAX_PEAKS_PER_PAIR - 1].val) {
        g_pair_peaks[p][TDOA_MAX_PEAKS_PER_PAIR - 1].lag = lag;
        g_pair_peaks[p][TDOA_MAX_PEAKS_PER_PAIR - 1].val = val;
        g_pair_peaks[p][TDOA_MAX_PEAKS_PER_PAIR - 1].valid = 1;
        sort_pair_peaks_desc(p);
    }
}
static void extract_gcc_peaks_for_pair(int p)
{
    g_pair_peak_count[p] = 0;
    for (int i = 0; i < TDOA_MAX_PEAKS_PER_PAIR; i++) {
        g_pair_peaks[p][i].lag = 0.0f;
        g_pair_peaks[p][i].val = -1e30f;
        g_pair_peaks[p][i].valid = 0;
    }
    int maxlag = g_maxlag_samp;
    if (maxlag < 2) return;
    for (int lag = -maxlag + 1; lag <= maxlag - 1; lag++) {
        float ym = gcc_at_int_lag(gcc_time[p], lag - 1);
        float y0 = gcc_at_int_lag(gcc_time[p], lag);
        float yp = gcc_at_int_lag(gcc_time[p], lag + 1);
        if (!(y0 > ym && y0 >= yp)) continue;
        float delta = 0.0f;
        float denom = ym - 2.0f * y0 + yp;
        if (fabsf(denom) > 1e-12f) {
            delta = 0.5f * (ym - yp) / denom;
            delta = clampf(delta, -0.5f, 0.5f);
        }
        float lag_f = (float)lag + delta;
        float val = gcc_at_lag_interp(gcc_time[p], lag_f);
        insert_pair_peak_sorted(p, lag_f, val);
    }
    /* If no local max was found due to a very flat GCC, fall back to the best sample. */
    if (g_pair_peak_count[p] == 0) {
        float best_v = -1e30f;
        int best_lag = 0;
        for (int lag = -maxlag; lag <= maxlag; lag++) {
            float v = gcc_at_int_lag(gcc_time[p], lag);
            if (v > best_v) {
                best_v = v;
                best_lag = lag;
            }
        }
        insert_pair_peak_sorted(p, (float)best_lag, best_v);
    }
}
static void extract_gcc_peaks_all_pairs(void)
{
    for (int p = 0; p < NPAIR; p++) {
        extract_gcc_peaks_for_pair(p);
    }
}
static float predicted_lag_for_az0_pair(float az_deg, int p)
{
    float u[3];
    unitvec_from_az_el(az_deg, 0.0f, u);
    float tau = dot3(g_rij[p], u) / SPEED_OF_SOUND;
    float lag = tau * FS;
    return clampf(lag, (float)(-g_maxlag_samp), (float)g_maxlag_samp);
}
static float tdoa_assignment_cost_for_peak(const doa_cand_t *cand, int p, int peak_idx)
{
    if (peak_idx < 0) return TDOA_MISSING_PAIR_COST;
    if (peak_idx >= (int)g_pair_peak_count[p]) return ASSOC_COST_INVALID;
    if (!g_pair_peaks[p][peak_idx].valid) return ASSOC_COST_INVALID;
    float base = predicted_lag_for_az0_pair(cand->az, p);
    float lag  = g_pair_peaks[p][peak_idx].lag;
    float val  = g_pair_peaks[p][peak_idx].val;
    float lo, hi;
    /* For a planar array, elevation scales the horizontal TDOA by rho=cos(el).
     * Therefore, for a fixed azimuth, valid lags lie approximately on the segment
     * between rho_min*base and base. */
    if (fabsf(base) < 0.08f) {
        lo = -TDOA_ASSIGN_GATE_SAMP;
        hi = +TDOA_ASSIGN_GATE_SAMP;
    } else {
        float rho_lag = TDOA_MIN_RHO * base;
        lo = fminf(base, rho_lag) - TDOA_ASSIGN_GATE_SAMP;
        hi = fmaxf(base, rho_lag) + TDOA_ASSIGN_GATE_SAMP;
    }
    if (lag < lo || lag > hi) return ASSOC_COST_INVALID;
    {
        float seg_lo, seg_hi;
        if (fabsf(base) < 0.08f) {
            seg_lo = 0.0f;
            seg_hi = 0.0f;
        } else {
            float rho_lag = TDOA_MIN_RHO * base;
            seg_lo = fminf(base, rho_lag);
            seg_hi = fmaxf(base, rho_lag);
        }
        float lag_on_seg = clampf(lag, seg_lo, seg_hi);
        float dist = fabsf(lag - lag_on_seg);
        /* Smaller distance is better. Higher GCC peak is better.
         * The peak term is intentionally weak to avoid one loud source stealing both tracks. */
        return dist - TDOA_PEAK_SCORE_COST_WEIGHT * val;
    }
}
static void assign_tdoa_peaks_exclusive(
    const doa_cand_t top2[TOPK_DOA],
    int peak_idx[TOPK_DOA][NPAIR])
{
    for (int c = 0; c < TOPK_DOA; c++) {
        for (int p = 0; p < NPAIR; p++) {
            peak_idx[c][p] = -1;
        }
    }
    for (int p = 0; p < NPAIR; p++) {
        float best_cost = ASSOC_COST_INVALID;
        int best_i0 = -1;
        int best_i1 = -1;
        /* Candidate -1 means this pair is not used for that source. */
        for (int i0 = -1; i0 < (int)g_pair_peak_count[p]; i0++) {
            float c0 = tdoa_assignment_cost_for_peak(&top2[0], p, i0);
            if (c0 >= ASSOC_COST_INVALID * 0.5f) continue;
            for (int i1 = -1; i1 < (int)g_pair_peak_count[p]; i1++) {
                if (i0 >= 0 && i1 >= 0 && i0 == i1) continue;
                float c1 = tdoa_assignment_cost_for_peak(&top2[1], p, i1);
                if (c1 >= ASSOC_COST_INVALID * 0.5f) continue;
                float total = c0 + c1;
                /* Prefer using a valid pair over leaving both missing. */
                if (i0 < 0 && i1 < 0) total += 0.25f;
                if (total < best_cost) {
                    best_cost = total;
                    best_i0 = i0;
                    best_i1 = i1;
                }
            }
        }
        peak_idx[0][p] = best_i0;
        peak_idx[1][p] = best_i1;
    }
}
static int solve_tdoa_ls_xy_from_assigned_peaks(
    const int peak_idx_for_cand[NPAIR],
    float *az_deg,
    float *el_abs_deg,
    float *resid_out)
{
    float Sxx = 0.0f, Sxy = 0.0f, Syy = 0.0f;
    float Sxb = 0.0f, Syb = 0.0f;
    int valid_pairs = 0;
    for (int p = 0; p < NPAIR; p++) {
        int idx = peak_idx_for_cand[p];
        if (idx < 0) continue;
        if (idx >= (int)g_pair_peak_count[p]) continue;
        if (!g_pair_peaks[p][idx].valid) continue;
        float ax = g_rij[p][0];
        float ay = g_rij[p][1];
        float tau = g_pair_peaks[p][idx].lag / FS;
        float b = SPEED_OF_SOUND * tau;
        float peak_val = g_pair_peaks[p][idx].val;
        if (peak_val < 0.0f) peak_val = 0.0f;
        float w = g_wpair[p] * (0.05f + peak_val);
        if (w < 1e-12f) w = 1e-12f;
        Sxx += w * ax * ax;
        Sxy += w * ax * ay;
        Syy += w * ay * ay;
        Sxb += w * ax * b;
        Syb += w * ay * b;
        valid_pairs++;
    }
    if (valid_pairs < TDOA_MIN_VALID_PAIRS) {
        return 0;
    }
    float det = Sxx * Syy - Sxy * Sxy;
    if (fabsf(det) < 1e-18f) {
        return 0;
    }
    float ux = ( Syy * Sxb - Sxy * Syb) / det;
    float uy = (-Sxy * Sxb + Sxx * Syb) / det;
    float rho = sqrtf(ux * ux + uy * uy);
    /* rho > 1 is physically impossible for a far-field unit vector.
     * Small overshoot can happen due to noise, so clamp mildly.
     * Large overshoot means peak association probably failed. */
    if (rho > 1.15f) {
        return 0;
    }
    rho = clampf(rho, TDOA_MIN_RHO, 1.0f);
    float az = atan2f(uy, ux) * (180.0f / PI);
    if (az < 0.0f) az += 360.0f;
    float el_abs = acosf(rho) * (180.0f / PI);
    el_abs = clampf(el_abs, 0.0f, TDOA_MAX_EL_DEG);
    {
        float err = 0.0f;
        float wsum = 0.0f;
        for (int p = 0; p < NPAIR; p++) {
            int idx = peak_idx_for_cand[p];
            if (idx < 0) continue;
            if (idx >= (int)g_pair_peak_count[p]) continue;
            if (!g_pair_peaks[p][idx].valid) continue;
            float ax = g_rij[p][0];
            float ay = g_rij[p][1];
            float tau = g_pair_peaks[p][idx].lag / FS;
            float b = SPEED_OF_SOUND * tau;
            float peak_val = g_pair_peaks[p][idx].val;
            if (peak_val < 0.0f) peak_val = 0.0f;
            float w = g_wpair[p] * (0.05f + peak_val);
            if (w < 1e-12f) w = 1e-12f;
            float pred = ax * ux + ay * uy;
            float e = b - pred;
            err += w * e * e;
            wsum += w;
        }
        if (wsum < 1e-12f) return 0;
        if (resid_out) {
            *resid_out = sqrtf(err / wsum);
        }
        if (sqrtf(err / wsum) > TDOA_LS_RESID_MAX_M) {
            return 0;
        }
    }
    if (az_deg) *az_deg = az;
#if TDOA_ASSUME_SOURCE_ABOVE_ARRAY
    if (el_abs_deg) *el_abs_deg = el_abs;
#else
    if (el_abs_deg) *el_abs_deg = -el_abs;
#endif
    return 1;
}
static void refine_top2_elevation_exclusive(doa_cand_t top2[TOPK_DOA])
{
#if TDOA_ELEVATION_ENABLE
    int peak_idx[TOPK_DOA][NPAIR];
    for (int c = 0; c < TOPK_DOA; c++) {
        top2[c].el_valid = 0;
        top2[c].el_resid = 1e30f;
    }
    extract_gcc_peaks_all_pairs();
    assign_tdoa_peaks_exclusive(top2, peak_idx);
    for (int c = 0; c < TOPK_DOA; c++) {
        float ls_az = 0.0f;
        float ls_el = 0.0f;
        float resid = 1e30f;
        if (solve_tdoa_ls_xy_from_assigned_peaks(peak_idx[c], &ls_az, &ls_el, &resid)) {
            /* Do not let LS override the robust SRP azimuth unless it agrees.
             * Elevation is the added information; azimuth tracking stays SRP/KF based. */
            if (angdiff_deg(ls_az, top2[c].az) <= 35.0f) {
                top2[c].el = ls_el;
                top2[c].el_valid = 1;
                top2[c].el_resid = resid;
            }
        }
    }
#else
    for (int c = 0; c < TOPK_DOA; c++) {
        top2[c].el = 0.0f;
        top2[c].el_valid = 0;
        top2[c].el_resid = 1e30f;
    }
#endif
}
static void kf_predict_track(doa_track_t *tr);
static void update_track_delays(doa_track_t *tr);
/* =========================================================
 * SRP scan quality helpers
 * ========================================================= */
static void SRP_UpdatePairPeaks(void)
{
    for (int p = 0; p < NPAIR; p++) {
        float best = -1e30f;
        int best_lag = 0;

        /* Find the strongest GCC-PHAT peak inside the physically valid lag range. */
        for (int lag = -g_maxlag_samp; lag <= g_maxlag_samp; lag++) {
            float v = gcc_at_int_lag(gcc_time[p], lag);
            if (v > best) {
                best = v;
                best_lag = lag;
            }
        }

        /*
         * 3-point parabolic interpolation gives a fractional-sample delay.
         * This is debug-only; SRP scoring itself is not changed.
         */
        float lag_f = (float)best_lag;
        if ((best_lag > -g_maxlag_samp) &&
            (best_lag <  g_maxlag_samp)) {
            float ym = gcc_at_int_lag(gcc_time[p], best_lag - 1);
            float y0 = gcc_at_int_lag(gcc_time[p], best_lag);
            float yp = gcc_at_int_lag(gcc_time[p], best_lag + 1);
            float denom = ym - (2.0f * y0) + yp;

            if (fabsf(denom) > 1e-12f) {
                float delta = 0.5f * (ym - yp) / denom;
                delta = clampf(delta, -0.5f, 0.5f);
                lag_f += delta;
            }
        }

        g_srp_pair_peak[p] = best;
        g_dbg_gcc_peak_lag[p] = lag_f;
        g_dbg_gcc_peak_val[p] = best;
    }
}
static float SRP_ScoreAtAz(float az_deg, uint8_t *out_support)
{
    float u[3];
    float score = 0.0f;
    uint8_t support = 0U;
    unitvec_from_az_el(az_deg, 0.0f, u);
    for (int p = 0; p < NPAIR; p++) {
        float tau = dot3(g_rij[p], u) / SPEED_OF_SOUND;
        float lag_f = clampf(tau * FS, (float)(-g_maxlag_samp), (float)g_maxlag_samp);
        float v = gcc_at_lag_interp(gcc_time[p], lag_f);
        score += g_wpair[p] * v;
        if ((g_srp_pair_peak[p] > 0.0f) &&
            (v >= SRP_PAIR_SUPPORT_PEAK_RATIO * g_srp_pair_peak[p])) {
            support++;
        }
    }
    if (out_support) *out_support = support;
#if (SRP_USE_PAIR_CONSISTENCY != 0)
    if (support < SRP_PAIR_MIN_SUPPORT) return -1e30f;
#endif
    return score;
}
#if (SRP_USE_SUBBAND_VOTING != 0)
static float SRP_SubbandScoreAtAz(int band, float az_deg)
{
    float u[3];
    float score = 0.0f;
    unitvec_from_az_el(az_deg, 0.0f, u);
    for (int p = 0; p < NPAIR; p++) {
        float tau = dot3(g_rij[p], u) / SPEED_OF_SOUND;
        float lag_f = clampf(tau * FS, (float)(-g_maxlag_samp), (float)g_maxlag_samp);
        float v = gcc_at_lag_interp(g_srp_subband_gcc[band][p], lag_f);
        score += g_wpair[p] * v;
    }
    return score;
}
static uint8_t SRP_GetSubbandConsensus(float *out_consensus)
{
    float best_az[SRP_SUBBAND_COUNT] = {0.0f, 0.0f, 0.0f};
    for (int b = 0; b < SRP_SUBBAND_COUNT; b++) {
        float best_score = -1e30f;
        for (int az = AZ_MIN_DEG; az <= AZ_MAX_DEG; az += AZ_STEP_DEG) {
            float sc = SRP_SubbandScoreAtAz(b, (float)az);
            if (sc > best_score) {
                best_score = sc;
                best_az[b] = (float)az;
            }
        }
        g_srp_dbg_band_az[b] = best_az[b];
    }
    /* Find the largest mutually-close cluster. With 3 bands this is simple. */
    uint8_t best_count = 1U;
    float best_consensus = best_az[0];
    for (int seed = 0; seed < SRP_SUBBAND_COUNT; seed++) {
        float sx = 0.0f, sy = 0.0f;
        uint8_t count = 0U;
        for (int b = 0; b < SRP_SUBBAND_COUNT; b++) {
            if (angdiff_deg(best_az[b], best_az[seed]) <= SRP_SUBBAND_AGREE_DEG) {
                float rad = best_az[b] * (PI / 180.0f);
                sx += arm_cos_f32(rad);
                sy += arm_sin_f32(rad);
                count++;
            }
        }
        if (count > best_count) {
            float az = atan2f(sy, sx) * (180.0f / PI);
            if (az < 0.0f) az += 360.0f;
            best_count = count;
            best_consensus = az;
        }
    }
    g_srp_dbg_band_agree = best_count;
    g_srp_dbg_band_consensus_az = best_consensus;
    if (out_consensus) *out_consensus = best_consensus;
    return best_count;
}
#endif
static void SRP_PredictTracksOnRejectedMeasurement(void)
{
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) continue;
        kf_predict_track(&g_tracks[t]);
        g_tracks[t].kf_x1 *= TRACK_VEL_DAMP_WHEN_MISS;
        g_tracks[t].az_vel_deg = g_tracks[t].kf_x1;
        g_tracks[t].az_deg = wrap_deg_360(g_tracks[t].kf_x0);
        update_track_delays(&g_tracks[t]);
        /* Deliberately do not increment miss: this is an uncertain measurement,
         * not confirmed silence or disappearance. */
    }
}
/* =========================================================
 * Top-2 SRP scan
 * ========================================================= */
static void srp_scan_top2(doa_cand_t out2[TOPK_DOA])
{
    g_srp_frame_valid = 1U;
    g_srp_dbg_peak_conf_ok = 1U;
    g_srp_dbg_band_agree = 0U;
    g_srp_dbg_best_pair_support = 0U;
    for (int i = 0; i < TOPK_DOA; i++) {
        out2[i].az = 0.0f;
        out2[i].el = 0.0f;
        out2[i].score = -1e30f;
        out2[i].el_valid = 0U;
        out2[i].el_resid = 1e30f;
    }
    SRP_UpdatePairPeaks();
    int gi = 0;
    for (int az = AZ_MIN_DEG; az <= AZ_MAX_DEG; az += AZ_STEP_DEG, gi++) {
        uint8_t support = 0U;
        g_srp_grid_score[gi] = SRP_ScoreAtAz((float)az, &support);
        g_srp_grid_pair_support[gi] = support;
    }
    float consensus_az = 0.0f;
#if (SRP_USE_SUBBAND_VOTING != 0)
    uint8_t agree = SRP_GetSubbandConsensus(&consensus_az);
    if (agree < SRP_SUBBAND_MIN_AGREE) {
        g_srp_frame_valid = 0U;
    }
#else
    (void)consensus_az;
#endif
    /* Pick TOPK candidates from the broadband score grid. When sub-band voting
     * is enabled, only accept broadband peaks near the sub-band consensus. */
    for (int slot = 0; slot < TOPK_DOA; slot++) {
        float best_score = -1e30f;
        float best_az = 0.0f;
        uint8_t best_support = 0U;
        gi = 0;
        for (int az = AZ_MIN_DEG; az <= AZ_MAX_DEG; az += AZ_STEP_DEG, gi++) {
            float sc = g_srp_grid_score[gi];
            if (sc <= best_score) continue;
#if (SRP_USE_SUBBAND_VOTING != 0)
            if (angdiff_deg((float)az, consensus_az) > SRP_SUBBAND_SEARCH_GATE_DEG) continue;
#endif
            uint8_t blocked = 0U;
            for (int prev = 0; prev < slot; prev++) {
                if ((out2[prev].score > -1e20f) &&
                    (angdiff_deg((float)az, out2[prev].az) < TOPK_AZ_SEP_DEG)) {
                    blocked = 1U;
                    break;
                }
            }
            if (blocked) continue;
            best_score = sc;
            best_az = (float)az;
            best_support = g_srp_grid_pair_support[gi];
        }
        if (best_score > -1e20f) {
            out2[slot].az = best_az;
            out2[slot].score = best_score;
            out2[slot].el = 0.0f;
            out2[slot].el_valid = 0U;
            out2[slot].el_resid = 1e30f;
            if (slot == 0) g_srp_dbg_best_pair_support = best_support;
        } else {
            out2[slot].az = 0.0f;
            out2[slot].score = 0.0f;
            if (slot == 0) g_srp_frame_valid = 0U;
        }
    }
    /* Top1/Top2 confidence is computed independently from TOPK_DOA so this
     * works even when the project outputs only one source. */
    float best_az = out2[0].az;
    float best_score = out2[0].score;
    float second_score = -1e30f;
    float second_az = 0.0f;
    gi = 0;
    for (int az = AZ_MIN_DEG; az <= AZ_MAX_DEG; az += AZ_STEP_DEG, gi++) {
        if (angdiff_deg((float)az, best_az) < SRP_PEAK_CONF_SEP_DEG) continue;
        if (g_srp_grid_score[gi] > second_score) {
            second_score = g_srp_grid_score[gi];
            second_az = (float)az;
        }
    }
    if (second_score < -1e20f) second_score = 0.0f;
    float ratio = 999.0f;
    uint8_t conf_ok = 1U;
    if (best_score < SRP_PEAK_CONF_ABS_MIN) conf_ok = 0U;
    if (second_score > 0.0f) ratio = best_score / (second_score + EPS_PHAT);
    if ((second_score > 0.0f) && (ratio < SRP_PEAK_CONF_RATIO_MIN)) conf_ok = 0U;
    g_srp_dbg_best_az = best_az;
    g_srp_dbg_best_score = best_score;
    g_srp_dbg_second_az = second_az;
    g_srp_dbg_second_score = second_score;
    g_srp_dbg_peak_ratio = ratio;
    g_srp_dbg_peak_conf_ok = conf_ok;
#if (SRP_USE_PEAK_CONFIDENCE != 0)
    if (conf_ok == 0U) g_srp_frame_valid = 0U;
#endif
    g_srp_dbg_frame_valid = g_srp_frame_valid;
    if (g_srp_frame_valid == 0U) g_srp_dbg_rejected_frames++;
}
/* =========================================================
 * Track helpers
 * ========================================================= */
static void kf_init_track(doa_track_t *tr, float az_deg_meas)
{
    tr->kf_x0 = az_deg_meas;   /* start with wrapped angle as initial unwrapped */
    tr->kf_x1 = 0.0f;
    tr->kf_P00 = KF_P00_INIT;
    tr->kf_P01 = KF_P01_INIT;
    tr->kf_P10 = KF_P10_INIT;
    tr->kf_P11 = KF_P11_INIT;
    tr->az_deg = wrap_deg_360(tr->kf_x0);
    tr->az_vel_deg = tr->kf_x1;
}
static void kf_predict_track(doa_track_t *tr)
{
    /* x' = F x, F=[[1,1],[0,1]] in frame unit */
    float x0 = tr->kf_x0 + tr->kf_x1;
    float x1 = tr->kf_x1;
    /* P' = F P F^T + Q
       with F=[[1,1],[0,1]] */
    float P00 = tr->kf_P00 + tr->kf_P01 + tr->kf_P10 + tr->kf_P11 + KF_Q_AZ;
    float P01 = tr->kf_P01 + tr->kf_P11;
    float P10 = tr->kf_P10 + tr->kf_P11;
    float P11 = tr->kf_P11 + KF_Q_VEL;
    tr->kf_x0 = x0;
    tr->kf_x1 = x1;
    tr->kf_P00 = P00;
    tr->kf_P01 = P01;
    tr->kf_P10 = P10;
    tr->kf_P11 = P11;
    tr->az_deg = wrap_deg_360(tr->kf_x0);
    tr->az_vel_deg = tr->kf_x1;
}
static void kf_update_track(doa_track_t *tr, float meas_az_deg_wrapped, float meas_score)
{
    /* unwrap measurement near predicted state */
    float z = unwrap_angle_near_ref_deg(meas_az_deg_wrapped, tr->kf_x0);
    float R = kf_measurement_noise_from_score(meas_score);
    /* innovation */
    float y = z - tr->kf_x0;
    /* S = HPH^T + R = P00 + R */
    float S = tr->kf_P00 + R;
    if (S < 1e-9f) S = 1e-9f;
    /* K = P H^T / S = [P00; P10]/S */
    float K0 = tr->kf_P00 / S;
    float K1 = tr->kf_P10 / S;
    /* state update */
    tr->kf_x0 = tr->kf_x0 + K0 * y;
    tr->kf_x1 = tr->kf_x1 + K1 * y;
    /* covariance update: P = (I-KH)P */
    {
        float P00 = (1.0f - K0) * tr->kf_P00;
        float P01 = (1.0f - K0) * tr->kf_P01;
        float P10 = tr->kf_P10 - K1 * tr->kf_P00;
        float P11 = tr->kf_P11 - K1 * tr->kf_P01;
        tr->kf_P00 = P00;
        tr->kf_P01 = P01;
        tr->kf_P10 = P10;
        tr->kf_P11 = P11;
    }
    tr->az_deg = wrap_deg_360(tr->kf_x0);
    tr->az_vel_deg = tr->kf_x1;
}
static int find_free_track_slot(void)
{
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) return t;
    }
    return -1;
}
static void update_track_delays(doa_track_t *tr)
{
    float u[3];
    unitvec_from_az_el(tr->az_deg, tr->el_deg, u);
    for (int m = 0; m < NMIC; m++) {
        float proj = g_mic_pos[m][0]*u[0] + g_mic_pos[m][1]*u[1] + g_mic_pos[m][2]*u[2];
        tr->tau_mic[m] = proj / SPEED_OF_SOUND;
    }
    float tau_min = tr->tau_mic[0];
    for (int m = 1; m < NMIC; m++) {
        if (tr->tau_mic[m] < tau_min) tau_min = tr->tau_mic[m];
    }
    for (int m = 0; m < NMIC; m++) {
        tr->tau_mic[m] -= tau_min;
    }
    for (int p = 0; p < NPAIR; p++) {
        tr->tau_pair[p] = dot3(g_rij[p], u) / SPEED_OF_SOUND;
    }
}
static void deactivate_track_slot(int t)
{
    uint32_t dead_id = g_tracks[t].id;
    g_tracks[t].active = 0;
    memset(g_tracks[t].ola_tail, 0, sizeof(g_tracks[t].ola_tail));
    memset(g_tracks[t].out_hop_i16, 0, sizeof(g_tracks[t].out_hop_i16));
    if (g_slot_track_id[0] == dead_id) g_slot_track_id[0] = 0;
    if (g_slot_track_id[1] == dead_id) g_slot_track_id[1] = 0;
}
static int is_far_enough_from_active_tracks(float az_deg, int except_t)
{
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (t == except_t) continue;
        if (!g_tracks[t].active) continue;
        if (g_tracks[t].miss > SLOT_COAST_MISS) continue;
        if (angdiff_deg(az_deg, g_tracks[t].az_deg) < ACTIVE_TRACK_MIN_SEP_DEG) {
            return 0;
        }
    }
    return 1;
}
static void track_birth_from_candidate(const doa_cand_t *cand)
{
    int slot = find_free_track_slot();
    if (slot < 0) return;
    if (cand->score < TRACK_BIRTH_SCORE) return;
    if (!is_far_enough_from_active_tracks(cand->az, -1)) return;
    g_tracks[slot].active   = 1;
    g_tracks[slot].id       = g_next_track_id++;
    g_tracks[slot].born_seq = g_next_born_seq++;
    g_tracks[slot].az_deg   = cand->az;
    g_tracks[slot].el_deg   = cand->el_valid ? cand->el : 0.0f;
    g_tracks[slot].score    = cand->score;
    g_tracks[slot].el_valid = cand->el_valid ? 1u : 0u;
    g_tracks[slot].el_resid = cand->el_valid ? cand->el_resid : 1e30f;
    g_tracks[slot].az_vel_deg = 0.0f;
    g_tracks[slot].age      = 1;
    g_tracks[slot].miss     = 0;
    memset(g_tracks[slot].ola_tail, 0, sizeof(g_tracks[slot].ola_tail));
    memset(g_tracks[slot].out_hop_i16, 0, sizeof(g_tracks[slot].out_hop_i16));
    kf_init_track(&g_tracks[slot], cand->az);
    update_track_delays(&g_tracks[slot]);
}
static void track_decay_all_when_long_silence(void)
{
    if (g_silence_hops <= SILENCE_HOLD_HOPS) return;
    if (((g_silence_hops - SILENCE_HOLD_HOPS) % SILENCE_DECAY_STRIDE) != 0u) return;
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) continue;
        kf_predict_track(&g_tracks[t]);
        g_tracks[t].miss++;
        g_tracks[t].kf_x1 *= TRACK_VEL_DAMP_WHEN_MISS;
        g_tracks[t].az_vel_deg = g_tracks[t].kf_x1;
        g_tracks[t].az_deg = wrap_deg_360(g_tracks[t].kf_x0);
        update_track_delays(&g_tracks[t]);
        if (g_tracks[t].miss > TRACK_DEATH_MISS) {
            deactivate_track_slot(t);
        }
    }
}
/* =========================================================
 * Association
 * ========================================================= */
static float association_cost(int t, const doa_cand_t *cand)
{
    if (!g_tracks[t].active) return ASSOC_COST_INVALID;
    if (cand->score < TRACK_BIRTH_SCORE) return ASSOC_COST_INVALID;
    /* predicted state from current predicted covariance/state
       note: caller should already have run kf_predict_track() this frame */
    float pred_az_unwrapped = g_tracks[t].kf_x0;
    float pred_az_wrapped   = wrap_deg_360(pred_az_unwrapped);
    float z_unwrapped = unwrap_angle_near_ref_deg(cand->az, pred_az_unwrapped);
    float innov = z_unwrapped - pred_az_unwrapped;
    float R = kf_measurement_noise_from_score(cand->score);
    float S = g_tracks[t].kf_P00 + R;
    if (S < 1e-9f) S = 1e-9f;
    float sigma = sqrtf(S);
    float daz = angdiff_deg(cand->az, pred_az_wrapped);
    float del = fabsf(cand->el - g_tracks[t].el_deg);
    if (fabsf(innov) > TRACK_MATCH_SIGMA_GATE * sigma) return ASSOC_COST_INVALID;
    if (daz > TRACK_MATCH_AZ_DEG * 1.8f) return ASSOC_COST_INVALID; /* secondary hard gate */
    if (del > TRACK_MATCH_EL_DEG) return ASSOC_COST_INVALID;
    for (int other = 0; other < MAX_TRACKS; other++) {
        if (other == t) continue;
        if (!g_tracks[other].active) continue;
        if (g_tracks[other].miss > SLOT_COAST_MISS) continue;
        if (angdiff_deg(cand->az, g_tracks[other].az_deg) < ACTIVE_TRACK_MIN_SEP_DEG) {
            return ASSOC_COST_INVALID;
        }
    }
	float mahal = (innov * innov) / S;
	float cost = 0.0f;
	cost += ASSOC_COST_MAHAL_WEIGHT * mahal;
	cost -= ASSOC_COST_SCORE_WEIGHT_KF * cand->score;
	cost -= ASSOC_COST_AGE_BONUS_KF * ((g_tracks[t].age > 0) ? 1.0f : 0.0f);
	return cost;
}
typedef struct {
    int track_of_cand[TOPK_DOA];
    float total_cost;
} assoc_solution_t;
static void solve_assoc_dfs(int cand_idx, uint8_t used_track[MAX_TRACKS], const float cost_mat[TOPK_DOA][MAX_TRACKS],
		assoc_solution_t *cur, assoc_solution_t *best)
{
    if (cand_idx >= TOPK_DOA) {
        if (cur->total_cost < best->total_cost) {
            *best = *cur;
        }
        return;
    }
    cur->track_of_cand[cand_idx] = -1;
    solve_assoc_dfs(cand_idx + 1, used_track, cost_mat, cur, best);
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (used_track[t]) continue;
        float c = cost_mat[cand_idx][t];
        if (c >= ASSOC_COST_INVALID * 0.5f) continue;
        used_track[t] = 1;
        cur->track_of_cand[cand_idx] = t;
        cur->total_cost += c;
        solve_assoc_dfs(cand_idx + 1, used_track, cost_mat, cur, best);
        cur->total_cost -= c;
        cur->track_of_cand[cand_idx] = -1;
        used_track[t] = 0;
    }
}
static void track_update_from_top2(const doa_cand_t top2[TOPK_DOA])
{
    float cost_mat[TOPK_DOA][MAX_TRACKS];
    uint8_t matched_track[MAX_TRACKS] = {0};
    /* 1) predict all active tracks first */
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) continue;
        kf_predict_track(&g_tracks[t]);
    }
    /* 2) build cost matrix from predicted states */
    for (int c = 0; c < TOPK_DOA; c++) {
        for (int t = 0; t < MAX_TRACKS; t++) {
            cost_mat[c][t] = association_cost(t, &top2[c]);
        }
    }
    assoc_solution_t cur, best;
    uint8_t used_track[MAX_TRACKS] = {0};
    for (int c = 0; c < TOPK_DOA; c++) cur.track_of_cand[c] = -1;
    cur.total_cost = 0.0f;
    for (int c = 0; c < TOPK_DOA; c++) best.track_of_cand[c] = -1;
    best.total_cost = 1e30f;
    solve_assoc_dfs(0, used_track, cost_mat, &cur, &best);
    /* 3) matched tracks: kalman update */
    for (int c = 0; c < TOPK_DOA; c++) {
        int t = best.track_of_cand[c];
        if (t < 0) continue;
        if (!g_tracks[t].active) continue;
        {
            float pred_unwrapped = g_tracks[t].kf_x0;
            float meas_unwrapped = unwrap_angle_near_ref_deg(top2[c].az, pred_unwrapped);
            float trial_wrapped  = wrap_deg_360(meas_unwrapped);
            /* keep anti-collapse rule against another active track */
            if (!is_far_enough_from_active_tracks(trial_wrapped, t)) {
                matched_track[t] = 0;
                continue;
            }
            kf_update_track(&g_tracks[t], top2[c].az, top2[c].score);
            if (top2[c].el_valid) {
                if (!g_tracks[t].el_valid) {
                    g_tracks[t].el_deg = top2[c].el;
                    g_tracks[t].el_valid = 1u;
                } else {
                    g_tracks[t].el_deg =
                        (1.0f - TDOA_LS_EL_SMOOTH_ALPHA) * g_tracks[t].el_deg + TDOA_LS_EL_SMOOTH_ALPHA * top2[c].el;
                }
                g_tracks[t].el_resid = top2[c].el_resid;
            }
            g_tracks[t].score  = 0.75f * g_tracks[t].score + 0.25f * top2[c].score;
            g_tracks[t].age++;
            g_tracks[t].miss = 0;
            update_track_delays(&g_tracks[t]);
            matched_track[t] = 1;
        }
    }
    /* 4) unmatched candidates => birth */
    for (int c = 0; c < TOPK_DOA; c++) {
        if (best.track_of_cand[c] >= 0) continue;
        if (top2[c].score < TRACK_BIRTH_SCORE) continue;
        if (!is_far_enough_from_active_tracks(top2[c].az, -1)) continue;
        track_birth_from_candidate(&top2[c]);
    }
    /* 5) unmatched existing tracks => coast */
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) continue;
        if (!matched_track[t]) {
            g_tracks[t].miss++;
            /* optional mild damping on predicted velocity */
            g_tracks[t].kf_x1 *= TRACK_VEL_DAMP_WHEN_MISS;
            g_tracks[t].az_vel_deg = g_tracks[t].kf_x1;
            g_tracks[t].az_deg = wrap_deg_360(g_tracks[t].kf_x0);
            update_track_delays(&g_tracks[t]);
            if (g_tracks[t].miss > TRACK_DEATH_MISS) {
                deactivate_track_slot(t);
            }
        }
    }
}
/* =========================================================
 * Output slot binding
 * ========================================================= */
static int find_track_index_by_id(uint32_t id)
{
    if (id == 0) return -1;
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) continue;
        if (g_tracks[t].id == id) return t;
    }
    return -1;
}
static void update_output_slots(int *idx0, int *idx1)
{
    *idx0 = -1;
    *idx1 = -1;
    {
        int t0 = find_track_index_by_id(g_slot_track_id[0]);
        int t1 = find_track_index_by_id(g_slot_track_id[1]);
        if (t0 >= 0 && g_tracks[t0].miss <= SLOT_COAST_MISS) {
            *idx0 = t0;
        } else {
            g_slot_track_id[0] = 0;
        }
        if (t1 >= 0 && g_tracks[t1].miss <= SLOT_COAST_MISS) {
            *idx1 = t1;
        } else {
            g_slot_track_id[1] = 0;
        }
    }
    for (int slot = 0; slot < 2; slot++) {
        if (g_slot_track_id[slot] != 0) continue;
        int best_t = -1;
        uint32_t best_age = 0;
        float best_score = -1e30f;
        for (int t = 0; t < MAX_TRACKS; t++) {
            if (!g_tracks[t].active) continue;
            if (g_tracks[t].miss > SLOT_COAST_MISS) continue;
            if (g_tracks[t].score < TRACK_BIRTH_SCORE) continue;
            {
                uint32_t id = g_tracks[t].id;
                if (id == 0) continue;
                if (id == g_slot_track_id[0] || id == g_slot_track_id[1]) continue;
                if ((slot == 1) && (g_slot_track_id[0] != 0)) {
                    int left_idx = find_track_index_by_id(g_slot_track_id[0]);
                    if (left_idx >= 0) {
                        if (angdiff_deg(g_tracks[t].az_deg, g_tracks[left_idx].az_deg) < ACTIVE_TRACK_MIN_SEP_DEG) {
                            continue;
                        }
                    }
                }
                if ((g_tracks[t].age > best_age) ||
                    (g_tracks[t].age == best_age && g_tracks[t].score > best_score)) {
                    best_age = g_tracks[t].age;
                    best_score = g_tracks[t].score;
                    best_t = t;
                }
            }
        }
        if (best_t >= 0) {
            g_slot_track_id[slot] = g_tracks[best_t].id;
        }
    }
    *idx0 = find_track_index_by_id(g_slot_track_id[0]);
    *idx1 = find_track_index_by_id(g_slot_track_id[1]);
}
/* =========================================================
 * Beamforming
 * ========================================================= */
static void beamform_one_track_freq(const doa_track_t *tr, float Y[NBINS][2])
{
    for (int k = 0; k < NBINS; k++) {
        float f = ((float)k * FS) / (float)NFFT;
        float yr = 0.0f;
        float yi = 0.0f;
        for (int m = 0; m < NMIC; m++) {
            float ph = 2.0f * PI * f * tr->tau_mic[m];
            float c = arm_cos_f32(ph);
            float s = arm_sin_f32(ph);
            float xr = Xc[m][k][0];
            float xi = Xc[m][k][1];
            float rr = xr * c - xi * s;
            float ii = xr * s + xi * c;
            yr += rr;
            yi += ii;
        }
        Y[k][0] = yr * OUTPUT_GAIN;
        Y[k][1] = yi * OUTPUT_GAIN;
    }
}
/* =========================================================
 * Soft mask score
 * ========================================================= */
static float compute_bin_direction_score_for_track(int track_idx, int k)
{
    float f = ((float)k * FS) / (float)NFFT;
    float score = 0.0f;
    float wsum  = 0.0f;
#if SOFTMASK_USE_BANDLIMIT
    {
        const float df = FS / (float)NFFT;
        int k0 = (int)(SRP_FMIN_HZ / df);
        int k1 = (int)(SRP_FMAX_HZ / df);
        if (k < k0 || k > k1) return SOFTMASK_MIN_SCORE;
    }
#endif
    if (!g_tracks[track_idx].active) return SOFTMASK_MIN_SCORE;
    if (k <= 0 || k >= (NBINS - 1)) return SOFTMASK_MIN_SCORE;
    for (int p = 0; p < NPAIR; p++) {
        uint8_t i = g_pairs[p].i;
        uint8_t j = g_pairs[p].j;
        float Xi_re = Xc[i][k][0];
        float Xi_im = Xc[i][k][1];
        float Xj_re = Xc[j][k][0];
        float Xj_im = Xc[j][k][1];
        float G_re = Xi_re * Xj_re + Xi_im * Xj_im;
        float G_im = Xi_im * Xj_re - Xi_re * Xj_im;
        float mag2 = G_re*G_re + G_im*G_im;
        if (mag2 < 1e-18f) continue;
        {
            float mag;
            arm_sqrt_f32(mag2, &mag);
            {
                float gnr = G_re / (mag + EPS_PHAT);
                float gni = G_im / (mag + EPS_PHAT);
                float ph = 2.0f * PI * f * g_tracks[track_idx].tau_pair[p];
                float er = arm_cos_f32(ph);
                float ei = arm_sin_f32(ph);
                float align = gnr * er + gni * ei;
                align = 0.5f * (align + 1.0f);
                align = clampf(align, 0.0f, 1.0f);
                score += g_wpair[p] * align;
                wsum  += g_wpair[p];
            }
        }
    }
    if (wsum < 1e-12f) return SOFTMASK_MIN_SCORE;
    score /= wsum;
    if (score < SOFTMASK_MIN_SCORE) score = SOFTMASK_MIN_SCORE;
    return score;
}
/* =========================================================
 * Soft mask
 * ========================================================= */
static void compute_track_bin_scores(void)
{
    for (int t = 0; t < MAX_TRACKS; t++) {
        for (int k = 0; k < NBINS; k++) {
            if (!g_tracks[t].active) {
                g_track_bin_score[t][k] = 0.0f;
            } else {
                g_track_bin_score[t][k] = compute_bin_direction_score_for_track(t, k);
            }
        }
    }
}
static void compute_soft_masks_from_scores(void)
{
    for (int k = 0; k < NBINS; k++) {
        float denom = 0.0f;
        float tmp[MAX_TRACKS];
        for (int t = 0; t < MAX_TRACKS; t++) {
            if (!g_tracks[t].active) {
                tmp[t] = 0.0f;
                continue;
            }
            {
                float s = g_track_bin_score[t][k];
                float v = fast_exp_approx(SOFTMASK_BETA * s);
                tmp[t] = v;
                denom += v;
            }
        }
        if (denom < 1e-20f) {
            for (int t = 0; t < MAX_TRACKS; t++) {
                g_track_bin_mask[t][k] = 0.0f;
            }
        } else {
            for (int t = 0; t < MAX_TRACKS; t++) {
                g_track_bin_mask[t][k] = tmp[t] / denom;
            }
        }
    }
}
static void apply_track_soft_mask(void)
{
#if SOFTMASK_ENABLE
    compute_track_bin_scores();
    compute_soft_masks_from_scores();
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) continue;
        for (int k = 0; k < NBINS; k++) {
            float m = g_track_bin_mask[t][k];
            Ytrk_bins[t][k][0] *= m;
            Ytrk_bins[t][k][1] *= m;
        }
    }
#endif
}
/* =========================================================
 * Synthesis
 * ========================================================= */
static void synthesize_one_track_to_hop(doa_track_t *tr, int track_idx)
{
    bins_pack_rfft(Ytrk_bins[track_idx], Ytrk_packed[track_idx]);
    arm_rfft_fast_f32(&g_rfft, Ytrk_packed[track_idx], ytrk_time[track_idx], 1);
    for (int n = 0; n < HOP_SIZE; n++) {
        float v = ytrk_time[track_idx][n] + tr->ola_tail[n];
        float next = ytrk_time[track_idx][n + HOP_SIZE];
        tr->ola_tail[n] = next;
        v = clampf(v, -1.0f, 1.0f);
        tr->out_hop_i16[n] = (int16_t)(v * 32767.0f);
    }
}
static void zero_track_output(doa_track_t *tr)
{
    memset(tr->out_hop_i16, 0, sizeof(tr->out_hop_i16));
}
/* =========================================================
 * Multi-track separation
 * ========================================================= */
static void separate_active_tracks(void)
{
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) {
            memset(Ytrk_bins[t], 0, sizeof(Ytrk_bins[t]));
            zero_track_output(&g_tracks[t]);
            continue;
        }
        beamform_one_track_freq(&g_tracks[t], Ytrk_bins[t]);
    }
    apply_track_soft_mask();
    for (int t = 0; t < MAX_TRACKS; t++) {
        if (!g_tracks[t].active) {
            zero_track_output(&g_tracks[t]);
            continue;
        }
        synthesize_one_track_to_hop(&g_tracks[t], t);
    }
}
/* =========================================================
 * Compatibility APIs
 * ========================================================= */
doa_result_t doa_process_frame(const int16_t *frame_interleaved_4ch)
{
    compute_gcc_phat_time(frame_interleaved_4ch);
    doa_cand_t top2[TOPK_DOA];
    doa_result_t r = {0};
    srp_scan_top2(top2);
    refine_top2_elevation_from_second_code(top2);
    r.active = (g_srp_frame_valid != 0U) ? 1U : 0U;
    r.id     = 0U;
    r.az_deg = top2[0].az;
    r.el_deg = top2[0].el_valid ? top2[0].el : 0.0f;
    r.score  = top2[0].score;
    r.el_valid = top2[0].el_valid;
    r.el_raw_deg = top2[0].el;
    r.el_resid = top2[0].el_resid;
    smooth_doa(&r);
    return r;
}
int doa_process_frame_top2(const int16_t *frame_interleaved_4ch, doa_result_t out[2])
{
    compute_gcc_phat_time(frame_interleaved_4ch);
    doa_cand_t top2[TOPK_DOA];
    srp_scan_top2(top2);
    refine_top2_elevation_from_second_code(top2);
    out[0].active = (g_srp_frame_valid != 0U) ? 1U : 0U;
    out[0].id     = 0U;
    out[0].az_deg = top2[0].az;
    out[0].el_deg = top2[0].el_valid ? top2[0].el : 0.0f;
    out[0].score  = top2[0].score;
    out[0].el_valid = top2[0].el_valid;
    out[0].el_raw_deg = top2[0].el;
    out[0].el_resid = top2[0].el_resid;
    smooth_doa(&out[0]);
#if (TOPK_DOA > 1)
    out[1].active = 1U;
    out[1].id     = 0U;
    out[1].az_deg = top2[1].az;
    out[1].el_deg = top2[1].el_valid ? top2[1].el : 0.0f;
    out[1].score  = top2[1].score;
    out[1].el_valid = top2[1].el_valid;
    out[1].el_raw_deg = top2[1].el;
    out[1].el_resid = top2[1].el_resid;
    return 2;
#else
    memset(&out[1], 0, sizeof(out[1]));
    return 1;
#endif
}
int doa_process_frame_separate(const int16_t *frame_interleaved_4ch, doa_result_t out_tracks[MAX_TRACKS])
{
    const uint8_t rms_release_tail = DOA_IsRmsReleaseTailActive(g_doa_active_stream);
    compute_gcc_phat_time(frame_interleaved_4ch);
    doa_cand_t top2[TOPK_DOA];
    srp_scan_top2(top2);
#if TDOA_ELEVATION_ENABLE
    refine_top2_elevation_from_second_code(top2);
#else
    for (int c = 0; c < TOPK_DOA; c++) {
        top2[c].el = 0.0f;
        top2[c].el_valid = 0U;
        top2[c].el_resid = 1e30f;
    }
#endif
    if (g_srp_frame_valid != 0U) {
        track_update_from_top2(top2);
    } else {
        SRP_PredictTracksOnRejectedMeasurement();
    }
    /*
     * 각도만 BF steering/LED에 사용할 때는 track별 오디오 분리까지
     * 계산할 필요가 없습니다. 이 함수는 beamforming + soft mask + IFFT까지
     * 수행하므로 DOA 반응을 느리게 만들 수 있습니다.
     *
     * 나중에 out_hop_i16[] 기반의 track별 분리 오디오가 필요할 때만 켜세요.
     */
    // separate_active_tracks();
    {
        int slot_idx0, slot_idx1;
        update_output_slots(&slot_idx0, &slot_idx1);
        for (int slot = 0; slot < MAX_TRACKS; slot++) {
            int track_idx = (slot == 0) ? slot_idx0 : slot_idx1;
            if (track_idx >= 0) {
                out_tracks[slot].active = 1U;
                out_tracks[slot].id     = g_tracks[track_idx].id;
                out_tracks[slot].az_deg = g_tracks[track_idx].az_deg;
                out_tracks[slot].el_deg = g_tracks[track_idx].el_valid ? g_tracks[track_idx].el_deg : 0.0f;
                out_tracks[slot].score  = g_tracks[track_idx].score;
                if (rms_release_tail == 0U) {
                    set_hold_from_slot_result(slot, out_tracks[slot].az_deg, out_tracks[slot].el_deg);
                }
            } else {
                float hold_az = 0.0f;
                float hold_el = 0.0f;
                uint8_t hold_valid = 0;
                get_hold_for_slot(slot, &hold_az, &hold_el, &hold_valid);
                out_tracks[slot].active = 0U;
                out_tracks[slot].id     = 0U;
                out_tracks[slot].az_deg = hold_valid ? hold_az : 0.0f;
                out_tracks[slot].el_deg = hold_valid ? hold_el : 0.0f;
                out_tracks[slot].score  = 0.0f;
            }
        }
        /*
         * Fallback:
         * SRP-PHAT top2는 잡혔지만 track birth/association/output slot binding이
         * 실패한 프레임에서는 primary output만 top2[0]로 강제 출력합니다.
         * 이렇게 하면 doa_process_frame_top2()처럼 놓치지 않으면서,
         * track이 정상화되면 다시 tracking 결과를 사용합니다.
         */
        if ((g_srp_frame_valid != 0U) &&
            (out_tracks[0].active == 0U) &&
            (top2[0].score > PRIMARY_DOA_FALLBACK_SCORE)) {
            out_tracks[0].active = 1U;
            out_tracks[0].id     = 0U;
            out_tracks[0].az_deg = top2[0].az;
            out_tracks[0].el_deg = top2[0].el_valid ? top2[0].el : 0.0f;
            out_tracks[0].score  = top2[0].score;
            if (rms_release_tail == 0U) {
                smooth_doa(&out_tracks[0]);
                set_hold_from_slot_result(0, out_tracks[0].az_deg, out_tracks[0].el_deg);
            }
        }
        /*
         * Release-tail output freeze.
         * SRP/tracking may continue internally, but the public primary DOA is
         * held at the last accepted direction so LED/latest output cannot end
         * on a late false peak such as 90 deg.
         */
        if ((rms_release_tail != 0U) && (g_hold_valid_l != 0U)) {
            out_tracks[0].az_deg = g_hold_az_l;
            out_tracks[0].el_deg = g_hold_el_l;
        }
        /* Raw TDOA-LS measurement used by main.c frame-quality selection. */
        out_tracks[0].el_valid = top2[0].el_valid;
        out_tracks[0].el_raw_deg = top2[0].el;
        out_tracks[0].el_resid = top2[0].el_resid;
    }
    return MAX_TRACKS;
}
/* =========================================================
 * RMS gate
 * ========================================================= */
static void DOA_UpdatePerChannelRmsDebug(const int16_t *frame_interleaved,
                                         uint32_t frame_size,
                                         uint32_t nmic,
                                         uint32_t stream_id)
{
    uint64_t sumsq[4] = {0U, 0U, 0U, 0U};
    uint32_t rms[4] = {0U, 0U, 0U, 0U};
    if ((frame_interleaved == NULL) || (frame_size == 0U) || (nmic < 4U))
    {
        return;
    }
    for (uint32_t i = 0U; i < frame_size; i++)
    {
        const uint32_t base = i * nmic;
        for (uint32_t ch = 0U; ch < 4U; ch++)
        {
            int32_t s = frame_interleaved[base + ch];
            sumsq[ch] += (uint64_t)(s * s);
        }
    }
    for (uint32_t ch = 0U; ch < 4U; ch++)
    {
        float rms_f = 0.0f;
        float ms_f = (float)(sumsq[ch] / frame_size);
        (void)arm_sqrt_f32(ms_f, &rms_f);
        rms[ch] = (uint32_t)rms_f;
    }
    if (stream_id == AUDIO_STREAM_L)
    {
        g_sai1a_rms_ch0 = rms[0];
        g_sai1a_rms_ch1 = rms[1];
        g_sai1a_rms_ch2 = rms[2];
        g_sai1a_rms_ch3 = rms[3];
    }
    else if (stream_id == AUDIO_STREAM_R)
    {
        g_sai1b_rms_ch0 = rms[0];
        g_sai1b_rms_ch1 = rms[1];
        g_sai1b_rms_ch2 = rms[2];
        g_sai1b_rms_ch3 = rms[3];
    }
}
static void DOA_AdaptiveRmsUpdateThresholds(doa_stream_context_t *ctx)
{
    float on_th;
    float off_th;
    if (ctx == NULL)
    {
        return;
    }
    ctx->rms_noise_floor = clampf(ctx->rms_noise_floor,
                                  RMS_NOISE_FLOOR_MIN,
                                  RMS_NOISE_FLOOR_MAX);
    on_th = ctx->rms_noise_floor * RMS_ON_RATIO;
    off_th = ctx->rms_noise_floor * RMS_OFF_RATIO;
    if (on_th < RMS_ON_MIN)
    {
        on_th = RMS_ON_MIN;
    }
    if (off_th < RMS_OFF_MIN)
    {
        off_th = RMS_OFF_MIN;
    }
    /* 항상 OFF threshold < ON threshold가 되도록 보장 */
    if (off_th >= on_th)
    {
        off_th = on_th * 0.75f;
        if (off_th < RMS_OFF_MIN)
        {
            off_th = RMS_OFF_MIN;
        }
    }
    ctx->rms_on_threshold = on_th;
    ctx->rms_off_threshold = off_th;
}
static uint8_t DOA_AdaptiveRmsGateProcess(doa_stream_context_t *ctx,
                                          uint32_t stream_id,
                                          uint32_t rms)
{
    uint8_t present;
    if (ctx == NULL)
    {
        return 0U;
    }
    present = ctx->audio_present_state;
    if (ctx->rms_noise_floor < RMS_NOISE_FLOOR_MIN)
    {
        ctx->rms_noise_floor = RMS_NOISE_FLOOR_INIT;
    }
    DOA_AdaptiveRmsUpdateThresholds(ctx);
    if (present == 0U)
    {
        /* 현재 noise floor 대비 충분히 큰 RMS가 연속으로 들어오면 speech ON */
        if ((float)rms >= ctx->rms_on_threshold)
        {
            if (ctx->rms_on_count < RMS_ON_CONFIRM_HOPS)
            {
                ctx->rms_on_count++;
            }
            if (ctx->rms_on_count >= RMS_ON_CONFIRM_HOPS)
            {
                present = 1U;
                ctx->rms_on_count = 0U;
                ctx->rms_off_count = 0U;
            }
        }
        else
        {
            float rms_f = (float)rms;
            float alpha;
            ctx->rms_on_count = 0U;
            ctx->rms_off_count = 0U;
            /*
             * speech가 아닌 구간에서만 noise floor를 학습한다.
             * noise 증가 방향은 천천히 추종하여 짧은 음성을 noise로
             * 흡수하는 것을 줄이고, noise 감소 방향은 조금 더 빠르게 추종한다.
             */
            alpha = (rms_f > ctx->rms_noise_floor) ?
                    RMS_NOISE_ALPHA_RISE : RMS_NOISE_ALPHA_FALL;
            ctx->rms_noise_floor =
                ((1.0f - alpha) * ctx->rms_noise_floor) +
                (alpha * rms_f);
            DOA_AdaptiveRmsUpdateThresholds(ctx);
        }
    }
    else
    {
        /*
         * speech 중에는 noise floor를 갱신하지 않는다.
         * OFF threshold 이하가 연속으로 유지될 때만 speech OFF.
         */
        ctx->rms_on_count = 0U;
        if ((float)rms <= ctx->rms_off_threshold)
        {
            if (ctx->rms_off_count < RMS_OFF_CONFIRM_HOPS)
            {
                ctx->rms_off_count++;
            }
            if (ctx->rms_off_count >= RMS_OFF_CONFIRM_HOPS)
            {
                present = 0U;
                ctx->rms_off_count = 0U;
            }
        }
        else
        {
            ctx->rms_off_count = 0U;
        }
    }
    ctx->audio_present_state = present;
    if (stream_id < DOA_MAX_SOURCES)
    {
        g_doa_noise_floor_stream[stream_id] =
            (uint32_t)(ctx->rms_noise_floor + 0.5f);
        g_doa_rms_on_threshold_stream[stream_id] =
            (uint32_t)(ctx->rms_on_threshold + 0.5f);
        g_doa_rms_off_threshold_stream[stream_id] =
            (uint32_t)(ctx->rms_off_threshold + 0.5f);
    }
    return present;
}
uint8_t audio_present_rms_i16(const int16_t *frame_interleaved,
                              uint32_t frame_size, uint32_t nmic,
                              uint32_t *out_rms_q0)
{
    uint64_t sumsq = 0U;
    uint32_t N = frame_size * nmic;
    uint32_t rms = 0U;
    if ((frame_interleaved == NULL) || (N == 0U))
    {
        if (out_rms_q0 != NULL)
        {
            *out_rms_q0 = 0U;
        }
        return 0U;
    }
    for (uint32_t i = 0U; i < N; i++)
    {
        int32_t sample = frame_interleaved[i];
        sumsq += (uint64_t)(sample * sample);
    }
    {
        uint32_t ms = (uint32_t)(sumsq / N);
        float rms_f = 0.0f;
        (void)arm_sqrt_f32((float)ms, &rms_f);
        rms = (uint32_t)rms_f;
    }
    if (out_rms_q0 != NULL)
    {
        *out_rms_q0 = rms;
    }
#if (RMS_ADAPTIVE_GATE_ENABLE != 0U)
    if (g_doa_active_stream < AUDIO_STREAM_COUNT)
    {
        doa_stream_context_t *ctx = &g_doa_ctx[g_doa_active_stream];
        g_audio_present_state =
            DOA_AdaptiveRmsGateProcess(ctx, g_doa_active_stream, rms);
    }
    else
    {
        g_audio_present_state = 0U;
    }
#else
    /* 기존 고정 RMS hysteresis fallback */
    if (g_audio_present_state == 0U)
    {
        if (rms >= RMS_PRESENT_ON_FIXED)
        {
            g_audio_present_state = 1U;
        }
    }
    else
    {
        if (rms <= RMS_PRESENT_OFF_FIXED)
        {
            g_audio_present_state = 0U;
        }
    }
#endif
    return g_audio_present_state;
}
