/* =========================================================
 * Public DOA snapshot API for SRP-PHAT -> AcousticBF handoff
 * ========================================================= */
static void DOA_UpdateLatestTracks(const doa_result_t in_tracks[DOA_MAX_SOURCES])
{
    uint8_t any_active = 0U;
    /* Public handoff is intentionally single-target only. */
    for (uint32_t i = 0U; i < DOA_MAX_SOURCES; i++)
    {
        g_latest_tracks[i] = in_tracks[i];
        if (in_tracks[i].active != 0U)
        {
            any_active = 1U;
        }
    }
    g_latest_tracks_valid = any_active;
    g_latest_tracks_seq++;
}
uint8_t DOA_GetLatestTracks(doa_result_t out[DOA_MAX_SOURCES])
{
    if (out == NULL)
    {
        return 0U;
    }
    for (uint32_t i = 0U; i < DOA_MAX_SOURCES; i++)
    {
        out[i] = g_latest_tracks[i];
    }
    return g_latest_tracks_valid;
}
uint8_t DOA_GetAudioPresentForStream(uint32_t stream_id)
{
    if (stream_id >= DOA_MAX_SOURCES)
    {
        return 0U;
    }
    return (uint8_t)g_doa_audio_present_stream[stream_id];
}
uint32_t DOA_GetLastRmsForStream(uint32_t stream_id)
{
    if (stream_id >= DOA_MAX_SOURCES)
    {
        return 0U;
    }
    return g_doa_last_rms_stream[stream_id];
}
uint32_t DOA_GetSilenceHopsForStream(uint32_t stream_id)
{
    if (stream_id >= DOA_MAX_SOURCES)
    {
        return 0U;
    }
    return g_doa_silence_hops_stream[stream_id];
}
uint8_t DOA_GetPrimaryTarget(float *az_deg, float *el_deg, uint32_t *track_id)
{
    if ((g_latest_tracks_valid == 0U) || (g_latest_tracks[0].active == 0U))
    {
        return 0U;
    }
    if (az_deg != NULL)
    {
        *az_deg = g_latest_tracks[0].az_deg;
    }
    if (el_deg != NULL)
    {
        *el_deg = g_latest_tracks[0].el_deg;
    }
    if (track_id != NULL)
    {
        *track_id = g_latest_tracks[0].id;
    }
    return 1U;
}
uint8_t DOA_GetPrimaryTargetForStream(uint32_t stream_id, float *az_deg, float *el_deg, uint32_t *track_id)
{
    if ((stream_id >= DOA_MAX_SOURCES) || (g_latest_tracks_valid == 0U) ||
        (g_latest_tracks[stream_id].active == 0U))
    {
        return 0U;
    }
    if (az_deg != NULL)
    {
        *az_deg = g_latest_tracks[stream_id].az_deg;
    }
    if (el_deg != NULL)
    {
        *el_deg = g_latest_tracks[stream_id].el_deg;
    }
    if (track_id != NULL)
    {
        *track_id = g_latest_tracks[stream_id].id;
    }
    return 1U;
}
/* =========================================================
 * Main process
 * ========================================================= */
static void DOA_SetLedForStream(uint32_t stream_id, float az_deg, uint8_t active)
{
    /*
     * Save the exact raw azimuth that enters the LED display path.
     * This is NOT quantized to 0/45/90/.../315. It is the same raw degree
     * argument that LED_L_op()/LED_R_op() receives.
     *
     * Important:
     *   When active == 0, keep the previous raw azimuth instead of
     *   overwriting it with 0 deg. This makes the PC azimuth display follow
     *   the LED-style hold behavior: no new valid LED angle -> keep the
     *   last displayed angle.
     */
    if (stream_id < DOA_MAX_SOURCES)
    {
        if (active != 0U)
        {
            g_doa_led_raw_az_deg_stream[stream_id] = az_deg;
            g_doa_led_raw_active_stream[stream_id] = 1U;
            g_doa_led_raw_seq_stream[stream_id]++;
        }
        else
        {
            g_doa_led_raw_active_stream[stream_id] = 0U;
        }
    }
    if (stream_id == AUDIO_STREAM_L)
    {
        if (active != 0U)
        {
            LED_L_op(az_deg);
        }
        else
        {
            LED_L_Init();
        }
    }
    else
    {
        /*
         * R(red) LED is reserved for Acoustic BF direction display.
         * Do not drive LED_R_op() from the SRP-PHAT azimuth here,
         * otherwise Degree_Proccess() overwrites the BF LED direction.
         *
         * The R LED is updated from main.c immediately after
         * BF_Latch_UpdateFromDoaTracks().
         */
//        if (active != 0U)
//        {
//            LED_R_op(az_deg);
//        }
//        else
//        {
//            LED_R_Init();
//        }
    }
}
uint8_t DOA_GetLedRawAzimuthForStream(uint32_t stream_id, float *az_deg, uint8_t *active)
{
    if (stream_id >= DOA_MAX_SOURCES)
    {
        return 0U;
    }
    if (az_deg != NULL)
    {
        *az_deg = g_doa_led_raw_az_deg_stream[stream_id];
    }
    if (active != NULL)
    {
        *active = (uint8_t)g_doa_led_raw_active_stream[stream_id];
    }
    return 1U;
}
static void DOA_UpdateLatestTrackOne(uint32_t stream_id, const doa_result_t *track)
{
    if ((stream_id >= DOA_MAX_SOURCES) || (track == NULL))
    {
        return;
    }
    g_latest_tracks[stream_id] = *track;
}
static uint8_t Degree_ProcessOneStream(uint32_t stream_id)
{
    uint32_t snap_slot = 0U;
    uint32_t snap_seq = 0U;
    if ((stream_id >= AUDIO_STREAM_COUNT) ||
        (DOA_IsStreamActive(stream_id) == 0U))
    {
        return 0U;
    }
    /* 새 DOA hop이 없으면 바로 return. */
    if (DOA_ReadNextHop(stream_id, g_hop_i16, &snap_slot, &snap_seq) == 0U)
    {
        return 0U;
    }
    g_doa_input_hops++;
    g_hop_consumed_cnt = snap_seq;
    /* 512-sample frame 구성: 이전 256 samples/ch + 새 256 samples/ch */
    memmove(&g_frame_i16[0],
            &g_frame_i16[SHARED_HOP_WORDS],
            sizeof(int16_t) * SHARED_HOP_WORDS);
    memcpy(&g_frame_i16[SHARED_HOP_WORDS],
           g_hop_i16,
           sizeof(int16_t) * SHARED_HOP_WORDS);
    if (g_warm_hops < 2U)
    {
        g_warm_hops++;
        return 0U;
    }
    {
        uint32_t rms = 0U;
        uint8_t present = audio_present_rms_i16(
            g_frame_i16,
            AUDIO_FRAME_SAMPLES_PER_CH,
            AUDIO_NMIC,
            &rms
        );
        g_last_rms = rms;
        /* CubeIDE Watch용 SAI1_A/B 채널별 RMS 업데이트. */
        DOA_UpdatePerChannelRmsDebug(
            g_frame_i16,
            AUDIO_FRAME_SAMPLES_PER_CH,
            AUDIO_NMIC,
            stream_id
        );
        /*
         * 두 마이크보드 중 어느 쪽에 소리가 먼저 들어왔는지 감지.
         * 새 256-sample hop만 검사하기 위해 g_frame_i16 뒤쪽 half 사용.
         */
        DOA_FirstSoundUpdateOnset(stream_id, &g_frame_i16[SHARED_HOP_WORDS], snap_seq, rms, present);
        if (!present)
        {
            doa_result_t inactive = {0};
            if (stream_id < DOA_MAX_SOURCES) {
                g_doa_rms_release_tail_stream[stream_id] = 0U;
            }
#if (SRP_USE_COHERENCE_WEIGHT != 0)
            /* A new utterance may come from a different angle. Reset the temporal
             * coherence history once when speech transitions to silence so old
             * cross-spectrum phase does not suppress the next speaker direction. */
            if (g_silence_hops == 0U) {
                SRP_ResetCoherenceStream(stream_id);
            }
#endif
            /* Do not absorb a pending speech-onset frame into the spectral noise
             * model. rms_on_count is non-zero while the adaptive gate is confirming
             * an onset. */
#if (SRP_USE_BIN_SNR_GATE != 0)
            if (g_doa_ctx[stream_id].rms_on_count == 0U) {
                SRP_UpdateSpectralNoiseModel(g_frame_i16, stream_id);
            }
#endif
            g_silence_hops++;
            track_decay_all_when_long_silence();
            /*
             * PHAT-mode-independent LED hold.
             * Keep the last valid primary azimuth even if SOFT05 temporarily
             * has no persistent track ID. This gives SOFT05 the same visible
             * hold behavior as FULL mode during the coast interval.
             */
//            if ((g_hold_valid_l != 0U) &&
//                (g_silence_hops < LED_HOLD_HOPS))
//            {
//                DOA_SetLedForStream(stream_id, g_hold_az_l, 1U);
//            }
//            else
//            {
//                DOA_SetLedForStream(stream_id, 0.0f, 0U);
//            }
            inactive.active = 0U;
            inactive.id = 0U;
            inactive.az_deg = g_hold_valid_l ? g_hold_az_l : g_last_doa.az_deg;
            inactive.el_deg = g_hold_valid_l ? g_hold_el_l : g_last_doa.el_deg;
            inactive.score = 0.0f;
            DOA_UpdateLatestTrackOne(stream_id, &inactive);
            return 1U;
        }
        g_silence_hops = 0U;
    }
    doa_decim++;
    if (doa_decim < DOA_PROCESS_DECIM_HOPS)
    {
        return 0U;
    }
    doa_decim = 0U;
    {
        doa_result_t out_tracks[MAX_TRACKS];
        memset(out_tracks, 0, sizeof(out_tracks));
        g_doa_srp_runs++;
        doa_process_frame_separate(g_frame_i16, out_tracks);
        g_last_doa = out_tracks[0];
        DOA_UpdateLatestTrackOne(stream_id, &out_tracks[0]);
//        DOA_UART_PrintStream(stream_id, &out_tracks[0], g_last_rms);
        /*
         * 먼저 들어온 보드로 확정된 stream이면,
         * 그 stream의 SRP-PHAT 각도를 모터 target으로 갱신.
         */
        DOA_FirstSoundUpdateTarget(stream_id, &out_tracks[0], g_last_rms);
        if (out_tracks[0].active != 0U)
        {
            DOA_SetLedForStream(stream_id, out_tracks[0].az_deg, 1U);
        }
        else if (g_hold_valid_l != 0U)
        {
            /* Transient tracking miss: keep the last displayed azimuth. */
            DOA_SetLedForStream(stream_id, g_hold_az_l, 1U);
        }
        else
        {
            DOA_SetLedForStream(stream_id, 0.0f, 0U);
        }
#if ENABLE_DEBUG_PRINT
        output_tracks_debug_text();
#endif
    }
    (void)snap_slot;
    return 1U;
}
void Degree_Proccess(void)
{
    uint8_t any_active = 0U;
    uint8_t any_audio_present = 0U;
    uint32_t active_mask = DOA_GetActiveStreamMask();
    for (uint32_t stream = 0U; stream < AUDIO_STREAM_COUNT; stream++)
    {
        if (!AUDIO_STREAM_MASK_HAS(active_mask, stream))
        {
            g_doa_audio_present_stream[stream] = 0U;
            g_doa_last_rms_stream[stream] = 0U;
            g_doa_silence_hops_stream[stream] = 0U;
            if (stream < DOA_MAX_SOURCES)
            {
                g_latest_tracks[stream].active = 0U;
                g_latest_tracks[stream].id = 0U;
                g_latest_tracks[stream].score = 0.0f;
            }
            DOA_SetLedForStream(stream, 0.0f, 0U);
            continue;
        }
        DOA_LoadContext(stream);
        (void)Degree_ProcessOneStream(stream);
        DOA_SaveContext(stream);
    }
    for (uint32_t stream = 0U; stream < DOA_MAX_SOURCES; stream++)
    {
        if (AUDIO_STREAM_MASK_HAS(active_mask, stream) &&
            (g_latest_tracks[stream].active != 0U))
        {
            any_active = 1U;
        }
        if (AUDIO_STREAM_MASK_HAS(active_mask, stream) &&
            (g_doa_audio_present_stream[stream] != 0U))
        {
            any_audio_present = 1U;
        }
    }
    g_latest_tracks_valid = any_active;
    g_latest_tracks_seq++;
    DOA_FirstSoundMaintenance(any_audio_present);
    /* Keep L context loaded for compatibility with legacy debug APIs. */
    DOA_LoadContext(AUDIO_STREAM_L);
}
